    if (!nested.ok) return { ok:false, attempt:attemptEvidence(source,{http_status:nested.status,error_code:`HTTP_${nested.status}`,stage:'nested-download'}) };
    const bytes = probe ? await responseProbeBytes(nested, maxBytes) : await responseBytes(nested);
    const nestedType = String(nested.headers?.get?.('content-type') || metadata.mime_type || '').toLowerCase() || null;
