  const type = String(fragment.type || fragment.content_type || '').toUpperCase();
  const id = fragment.file_id || fragment.id || fragment.asset_pointer || null;
  const name = fragment.file_name || fragment.filename || fragment.name || null;
  const mime = fragment.mime_type || fragment.media_type || null;
  const size = Number(fragment.file_size ?? fragment.size);
  if (!(type === 'FILE' || id || name)) return null;
  if (!id && !name) return null;
