      platform: 'deepseek',
      account_scope: accountScope,
      workspace_scope: workspaceScope,
      completeness: accountScope && workspaceScope ? 'complete' : accountScope ? 'partial' : 'unknown',
      scope_basis: session.scope_basis || 'unknown',
