      io: store,
      registry,
      attachmentId: asset.attachment_id,
      bytes: fetched.bytes,
      preferredFilename: representative?.displayed_filename || entity.original_filename || entity.source_file_id || '',
      source: 'conversation',
      now,
      cryptoImpl,
