    asset.status = 'complete';
    asset.processing_state = 'closed';
    asset.actionable = false;
    asset.next_action = null;
    asset.error_code = null;
    asset.error = null;
    if (asset.failure_lifecycle) asset.failure_lifecycle = { ...asset.failure_lifecycle, next_action:'none', resolved_at:now() };
