const { buildMaterializationPlan } = require('./attachment-materialization-plan');
const { META_ROOT, META_ATTACHMENTS_PATH, LEGACY_META_ROOT } = require('../storage/meta-paths');



const HELPER_RELATIVE_WIN = `${META_ROOT.replace(/\//g, '\\')}\\materialize-attachments.ps1`;





const TAKEN_RECORD_RELATIVE_WIN = `${META_ROOT.replace(/\//g, '\\')}\\shelf-taken.jsonl`;

const CMD_FILE_NAME = '01 取回全部附件.cmd';

function normalizePath(value) {
  return String(value || '').replace(/\\/g, '/').replace(/^\/+|\/+$/g, '');
}




const CANONICAL_LIBRARY_ROOTS = ['20_文件库/', '文件库/'];

function isCanonicalLibraryPath(value) {
  const path = normalizePath(value);
  return CANONICAL_LIBRARY_ROOTS.some((root) => path.startsWith(root));
}

async function exists(io,path){if(typeof io?.exists==='function')return Boolean(await io.exists(path));try{await io.read(path);return true}catch(error){if(error?.name==='NotFoundError'||error?.code==='ENOENT')return false;throw error}}
function byteView(value){if(value instanceof Uint8Array)return value;if(value instanceof ArrayBuffer)return new Uint8Array(value);if(ArrayBuffer.isView(value))return new Uint8Array(value.buffer,value.byteOffset,value.byteLength);return new Uint8Array(value||[])}
function bytesEqual(left,right){const a=byteView(left),b=byteView(right);if(a.byteLength!==b.byteLength)return false;for(let i=0;i<a.byteLength;i++)if(a[i]!==b[i])return false;return true}

