function normEntryPath(value){return String(value||'').replace(/\\/g,'/').replace(/^\/+|\/+$/g,'')}
async function readHandleFile(rootHandle,path){const parts=normEntryPath(path).split('/').filter(Boolean),name=parts.pop(),dir=await getDirectoryHandleAt(rootHandle,parts.join('/'),{create:false}),handle=await dir.getFileHandle(name,{create:false}),file=await handle.getFile();return new Uint8Array(await file.arrayBuffer())}
async function removeHandleFileBestEffort(rootHandle,path){const parts=normEntryPath(path).split('/').filter(Boolean),name=parts.pop();if(!name)return false;try{const dir=await getDirectoryHandleAt(rootHandle,parts.join('/'),{create:false});await dir.removeEntry(name);return true}catch(error){if(error?.name==='NotFoundError')return false;throw error}}
function knownEntryFilePaths(knownItems=[]){const out=[];for(const item of knownItems||[]){const root=normEntryPath(item?.path||item?.name||'');if(!root)continue;if(!item?.directory){out.push(root);continue}for(const record of Array.isArray(item?.files)?item.files:[]){const explicit=normEntryPath(record?.path||'');if(explicit&&(explicit===root||explicit.startsWith(root+'/'))){out.push(explicit);continue}const name=normEntryPath(record?.name||'');if(name)out.push(`${root}/${name}`)}}return[...new Set(out)]}
async function snapshotKnownEntry(rootHandle,knownItems=[]){const files=[];for(const path of knownEntryFilePaths(knownItems)){try{files.push({path,bytes:await readHandleFile(rootHandle,path)})}catch(error){if(error?.name!=='NotFoundError')throw error}}return files}
