  if(!from)throw new Error('空目录名为空');
  if(!to)throw new Error('请给这个空夹选一个落点');
  const kinds=trackedFolderKinds();                 /* json / markdown / pdf / word，且已启用 */
  if(!kinds.length)throw new Error('这个库一层内容都没启用，落点无从谈起');
