function auditChangeRequiresUserDecision(change) {
  if (!change) return false;
  /* [REV-2026-10-08] **用户 2026-10-08 锁定的最终口径：待处理只允许 3 种出现**
     （`conflict/split-vector` = ① 落点矛盾；`title-candidate` = ②③ 网页新命名），
     其余一律 auto（插件自己修 / 自己记账），**界面上一律不许出现**。所以这条判据只认一种：
       · ① 落点矛盾 = `conflict` + `split-vector`（各层落在不同文件夹 → 选一个分类文件夹，所有层一起归过去）。
     已经从这条判据里撤掉的（全部转 auto，见 `local-audit` 的 `auto_settle` / `auto_notes`）：
       · `new-folder`（新建目录 = 新增向量）
       · `uncertain`（定位不确定**不存在**：没项目 → 去自命名；没分类 → 直接进「未归类」）
       · `repair`（账本与盘上不符：自动按盘上事实修 + 记账 —— 用户原话"我根本看不懂，没法拍板"）
       · `decide-empty-folder`（空夹：自动在其它所有层（含附件层）建同名文件夹，有内容不动）
       · `library-upgrade`（用户 2026-10-08 列进"其余旧类型 → where:auto"）
       · 附件侧那两类（`attachment-duplicate` / `attachment-ref-unreadable`）**不存在**。 */
  return change.major?.type === 'conflict' && change.major?.subtype === 'split-vector';
}
function autoSettleChangeDecision(change) {
  
  
  
  
  
  
  
  
  
  
  
  
  if (!change) return 'skip';
  /* [REV-2026-10-08] `auto_settle` 是**审计侧**对"这一笔怎么自动收"的直接结论，比按 type 猜更准：
       · `'ledger-only'` → `apply-ledger-only`：只记账，**盘上文件一个字不动**（`uncertain` 用它）；
       · `'apply'`        → 走下面那条 apply 链（`repair` 用它：按盘上事实归位 + 记账）。 */
  if (change.auto_settle === 'ledger-only' || change.major?.auto_settle === 'ledger-only') return 'apply-ledger-only';
  if (change.auto_settle === 'apply' || change.major?.auto_settle === 'apply') return 'apply';
  if (change.major?.type === 'delete') return 'apply-delete';
  if (change.major?.type === 'attachments-detached') return 'apply-detach';
  if (change.major?.type === 'gate-archive') return 'apply-gate-archive';
  if (change.major?.type === 'gate-unarchive') return 'apply-gate-unarchive';
  if (change.major?.type === 'gate-delete') return 'apply-gate-delete';
  if (change.major?.type === 'gate-restore') return 'apply-gate-restore';
  return 'apply';
}
function conversationNeedsSaveDeferral(change) {
  if (!(change?.conversation_uid||change?.conversation_id)) return false;
  /* [REV-2026-10-08] 只有**真的在等用户拍板**的那一种（`conflict/split-vector`）才顺延；
     其余（uncertain / repair / new-folder / 空夹 / 附件侧）都自动收掉了，不再顺延保存。 */
  return auditChangeRequiresUserDecision(change);
}
function ruleSaveFeedback(reclassified = [], { verb = '保存' } = {}) {
  
  
  
  
  
  const list = Array.isArray(reclassified) ? reclassified : [];
  const label = `自命名规则已${verb}`;
  const moved = list.filter((item) => item?.status === 'moved').length;
  const attention = list.filter((item) => item?.status === 'needs-attention');
  const total = list.length;
  if (!total) return { ok: true, message: label, moved: 0, attention: [] };
  if (!attention.length) return { ok: true, message: `${label}；${moved} 个对话已归位`, moved, attention: [] };
  const firstReason = attention[0]?.error || attention[0]?.error_code || '需要人工确认';
  const reasonText = attention.length === 1 ? `（${firstReason}）` : `（如：${firstReason}）`;
  return {
    ok: false,
    



    message: `${label}；${moved} 个已归位，${attention.length} 个没搬成${reasonText}`,
    moved,
    attention,
  };
}
function isConversationBlocking(change) {
  return Boolean((change?.conversation_uid||change?.conversation_id) && auditChangeRequiresUserDecision(change));
}
function fullSavePendingPolicy(pending = []) {
  const attention=(Array.isArray(pending)?pending:[]).filter((item)=>isConversationBlocking(item));
  const refs=[];
  for(const item of attention){
    if(!conversationNeedsSaveDeferral(item))continue;
    if(item.conversation_uid)refs.push(String(item.conversation_uid));
    if(item.conversation_id)refs.push(String(item.conversation_id));
  }
  return {attention,defer_conversation_refs:[...new Set(refs)]};
}
