  return { configured:false, formats:['json'], content_scope:'composed', include_attachments:false, output_kind:'zip', zip_mode:'preserve', batch_size:50, package_name:'', destination_name:'', history_retention:'ask_each_time', attachment_naming:{enabled:true,mode:'name-first',include_origin:true,include_order:true,include_time:false} };
