  async function reclassifyLocalConversations(rules, { onProgress=async()=>{}, conversationUids=null } = {}) {
    const { io } = await requireCurrent();
    const index = await loadIndex(io); const results=[];
    if(Array.isArray(conversationUids)&&conversationUids.length===0)return results;
    const attachmentRegistry=normalizeAttachmentRegistry(await optionalJson(io,ATTACHMENT_REGISTRY_PATH,null)||createEmptyAttachmentRegistry());
    const persistIndex = async (value) => saveIndex(io, value, now);
    const wanted=conversationUids?new Set((conversationUids||[]).map(String)):null;
    const rows=Object.entries(index.conversations || {}).filter(([uid])=>!wanted||wanted.has(String(uid))); let position=0;
    for (const [uid,entry] of rows) {
      position+=1; await onProgress({phase:'rule-scan',position,total:rows.length,title:entry?.title||'未命名对话'});
      if (!entry?.conversation_id || entry.local_state === 'deleted') continue;
      const resolved = resolveClassification({ conversationId:uid, title:entry.title, indexed:entry, rulesState:rules });
      const classification=lifecycleClassification(resolved,entry);
      if (sameClassification(classification, entry.classification)) continue;
      const paths = conversationAssetPathsForEntry({ title:entry.title, conversation_id:entry.storage_id||entry.conversation_id, classification, indexed:entry });
      try {
        await commitLocalRewrite({
          io, indexed:entry,
          remote:{ id:entry.conversation_id, title:entry.title, source_state:entry.source_state, update_time:entry.update_time },
          finalPaths:paths, index, persistIndex, conversationUid:uid, attachmentRegistry,
          classificationResolver:() => classification,
        });
        results.push({ conversation_uid:uid, conversation_id:entry.conversation_id, status:'moved', folder:classification.folder||classification.kind });
      } catch (error) {
        results.push({ conversation_uid:uid, conversation_id:entry.conversation_id, status:'needs-attention', error_code:error.code||error.name, error:error.message });
      }
    }
    attachmentRegistry.updated_at=now();
    await writeJsonVerified(io,ATTACHMENT_REGISTRY_PATH,attachmentRegistry);
    return results;
  }

  async function saveRule(ruleInput, { expectedRevision = null, seedFolder = null, seedTitleFormat = null, pairingFolder = null, pairingTitleFormat = null, onProgress=async()=>{} } = {}) {
    const { io } = await requireCurrent();
    await onProgress({phase:'validate',message:'正在确认 Rule…'});
    const current = await readRules(io);
    const normalized = normalizeRule({ ...ruleInput, rule_id:ruleInput?.rule_id || ruleId() });
    const validation = validateRuleAgainstRules(normalized,current.rules||[]);
    if (!validation.ok) { const e=new Error(validation.errors.join('；'));e.code='rule_invalid';e.errors=validation.errors;throw e; }
    if(pairingFolder){
      const target=normalizedFolder(ruleTargetFolder(normalized));
      const indexBefore=await loadIndex(io);
      const structureBefore=await readLibraryStructure({io});
      const pathEntries=typeof io.listPathEntries==='function'?await io.listPathEntries():null;
      const paths=pathEntries?pathEntries.map((entry)=>String(entry?.path||'')).filter(Boolean):(typeof io.listPaths==='function'?await io.listPaths():[]);
      const candidates=buildLocalPairingCandidates({paths,pathEntries,index:indexBefore,axis:effectiveAxis(structureBefore),rulesState:current});
      if(!candidates.some((item)=>normalizedFolder(item.folder)===target)){
        const e=new Error(`刚才选的本地目录「${target||pairingFolder}」已经不存在或现在不能作为自命名目标；请重新选择目录`);e.code='pairing_folder_stale';e.folder=target||pairingFolder;throw e;
      }
    }
    if(pairingTitleFormat){
      const selectedField=String(pairingTitleFormat.field||'').trim().toUpperCase();
      const selectedConnector=String(pairingTitleFormat.connector??'');
      if(normalized.field===selectedField&&normalized.connector===selectedConnector){
        const scan=await readTitleCandidateScan(io);
        if(scan.status!=='ok'){
          const e=new Error('网页命名候选缓存现在不可用；请重新执行「检查变化」后再保存配对');e.code='pairing_title_scan_stale';throw e;
        }
        const stillThere=titleCandidateGroups(scan.state.titles,current,{includeIgnored:true}).some((item)=>item.field===selectedField&&String(item.connector??'')===selectedConnector);
        if(!stillThere){const e=new Error('刚才选的网页命名候选已经不在当前扫描结果里；请重新选择');e.code='pairing_title_candidate_stale';throw e;}
      }
    }
    const next=upsertRuleState(current,normalized,{seedFolder:seedFolder?normalizedFolder(seedFolder):null,seedTitleFormat});
    await onProgress({phase:'write',message:'正在保存 Rule…'});
    const written = await writeRules(io, next, { expectedRevision:expectedRevision ?? current.revision, now });
    const index=await loadIndex(io);
    const changed=affectedConversationUids(index,current,written);
    const retryable=reclassificationTodoUids(index,written,{ruleIds:[normalized.rule_id]});
    const affected=[...new Set([...changed,...retryable])].sort();
    await onProgress({phase:'reclassify',message:'正在整理受影响的对话…',affected:affected.length});
    const reclassified = await reclassifyLocalConversations(written,{onProgress,conversationUids:affected});
    await onProgress({phase:'complete',message:'Rule 已保存',reclassified:reclassified.length});
    return { rules:written, rule:normalized, reclassified };
  }

  async function deleteRule(ruleIdValue, { expectedRevision = null } = {}) {
    const { io } = await requireCurrent(); const current=await readRules(io); const next=clone(current);
    next.rules=(next.rules||[]).filter((r)=>r.rule_id!==ruleIdValue);
    for(const [id,value] of Object.entries(next.conversation_overrides||{})) if(value?.rule_id===ruleIdValue) delete next.conversation_overrides[id];
    const written=await writeRules(io,next,{expectedRevision:expectedRevision??current.revision,now});
    const index=await loadIndex(io);
    const affected=[...new Set([...affectedConversationUids(index,current,written),...reclassificationTodoUids(index,written,{ruleIds:[ruleIdValue]})])].sort();
    const reclassified=await reclassifyLocalConversations(written,{conversationUids:affected}); return {rules:written,reclassified};
  }

  async function setConversationFolder(conversationId, folder) {
    const { io }=await requireCurrent(); const index=await loadIndex(io); const uid=resolveConversationUid(index,conversationId); if(!uid)throw new Error('对话 不在索引中');
    const entry=index.conversations?.[uid];
    const rules=await readRules(io); const next=clone(rules); const normalized=normalizedFolder(folder);
    const desired=lifecycleClassification(resolveClassification({conversationId:uid,title:entry?.title,indexed:entry,rulesState:rules}),entry);
    const keepRule=Boolean(normalized&&desired?.rule_id&&activeFolder(desired.folder)===activeFolder(normalized));
    const targetClassification=keepRule?{...desired,folder:normalized}:null;
    const moved=normalized?await applyMove({io,conversationId:uid,targetFolder:normalized,targetClassification,preserveClassification:keepRule,now}):null;
    if(!normalized||keepRule) delete next.conversation_overrides[uid];
    else next.conversation_overrides[uid]={folder:normalized,rule_id:null,source:'manual-folder-direct',updated_at:now()};
    const written=await writeRules(io,next,{expectedRevision:rules.revision,now});
    return {rules:written,conversation:moved};
  }

  /* [REV-2026-10-08] 用户定：「**忽略 = 这次不处理**」（准绳 6）。
     这四个函数（`ignoreFolder` / `unignoreFolder` / `ignoreRemoteTitleFormat` / `unignoreRemoteTitleFormat`）
     **已经没有任何调用方**：卡片上那一颗「忽略（这次不处理）」只回 `{action:'not-now'}`，
     **不再往 `ignored_folders` / `ignored_title_formats` 里写东西**；「已忽略」那一页也整页删了。
     这里保留函数定义（对外 API 面不改，旧库字段也照旧读），但它们已经是**死代码**，
     下一步要么整条删、要么明确重新接线 —— 不要以为它们还在工作。 */

  async function automaticSettle(io, audit) {
    const actions=[];
    
    
    
    
    
    
    
    const attention=[];
    if(!audit.trusted) return {actions,changed:false,attention};
    for(const change of audit.changes||[]) {
      const ref=change.conversation_uid||change.conversation_id;
      const settleDecision=autoSettleChangeDecision(change);
      if(settleDecision==='skip') continue;
      /* [REV-2026-10-08] 「只记账」这一路（`uncertain` / 定位不确定）：用户 2026-10-08 锁定这一格
         **不进待处理**，但也**不许动盘上文件**（说不清就是说不清）—— 所以只把它记进本轮 settle 账，
         盘上文件与索引**一个字都不改**。它下次检查还会按事实重算，不会丢。 */
      if(settleDecision==='apply-ledger-only') {
        actions.push({key:changeKey(change),action:'auto-ledger-only',reason:change?.major?.reason||change?.reason||'定位不确定：自动记账，不动盘上文件'});
        continue;
      }
      
      
      if(settleDecision==='apply-delete') {
        await applyDelete({io,conversationId:ref,change,deletionSource:'local',deletionReason:change?.major?.reason||'local-file-removed',now});
        actions.push({key:changeKey(change),action:'apply-local-delete'});
        continue;
      }
      
      
      if(settleDecision==='apply-detach') {
        const detachIndex=await loadIndex(io);
        const detachEntry=detachIndex?.conversations?.[ref]||null;
        if(detachEntry){
          const registryValue=await optionalJson(io,ATTACHMENT_REGISTRY_PATH,null);
          const detachRegistry=registryValue?normalizeAttachmentRegistry(registryValue):null;
          const detached=detachConversationAttachments({registry:detachRegistry,entry:detachEntry,conversationUid:ref,now});
          if(detached.changed){
            if(detachRegistry) await writeJsonVerified(io,ATTACHMENT_REGISTRY_PATH,detachRegistry);
            await saveIndex(io,detachIndex,now);
          }
          actions.push({key:changeKey(change),action:'apply-attachment-detach',recycled_relations:detached.recycled_relation_keys.length});
        }
        continue;
      }
      
      
      
      
      if(settleDecision==='apply-gate-archive') {
        
        
        
        await archiveConversation(ref, change);
        actions.push({key:changeKey(change),action:'apply-gate-archive'});
        continue;
      }
      if(settleDecision==='apply-gate-unarchive') {
        await unarchiveConversation(ref, change);
        actions.push({key:changeKey(change),action:'apply-gate-unarchive'});
        continue;
      }
      
      if(settleDecision==='apply-gate-delete') {
        await applyDelete({io,conversationId:ref,change,deletionSource:'local',deletionReason:'moved-into-deleted-gate',now});
        actions.push({key:changeKey(change),action:'apply-gate-delete'});
        continue;
      }
      
      if(settleDecision==='apply-gate-restore') {
        await restoreConversation(ref);
        actions.push({key:changeKey(change),action:'apply-gate-restore'});
        continue;
      }
      if(change.major?.renames?.length || change.major?.type==='rename') {
        await acceptLocalRenames({io,conversationId:ref,change,now});
        actions.push({key:changeKey(change),action:'accept-local-rename'});
      }
      if(change.major?.type==='move') { await applyMove({io,conversationId:ref,change,now}); actions.push({key:changeKey(change),action:'accept-move'}); continue; }
      /* [REV-2026-10-08] `repair`（账本与盘上不符，`auto_settle:'apply'`）：**自动按盘上事实归位 + 记账**。
         目标落点从审计给的 representations 里取（哪一层先给出唯一落点就用它）——不再问她，也不猜。 */
      if(change.major?.type==='repair') {
        const targetFolder=(change.major?.representations||[]).map((rep)=>rep?.to_folder||logicalFolderOfRepresentation(rep?.to,rep?.kind)).filter(Boolean)[0]||'';
        if(!targetFolder){ actions.push({key:changeKey(change),action:'auto-ledger-only',reason:'账本与盘上不符，但盘上没有唯一落点可归位；只记账，不动文件'}); continue; }
        await applyMove({io,conversationId:ref,change,targetFolder,now});
        actions.push({key:changeKey(change),action:'accept-repair-move'});
        continue;
      }
      
      
      
      
      
      
      const attachmentLocalChange=Boolean(
        change.attachments?.internal_moves?.length || change.attachments?.deletions?.length || change.attachments?.modifications?.length || change.attachments?.additions?.length || change.attachments?.archive_needed?.length || change.attachments?.collection_change?.type==='delete' || change.attachments?.relation_changes?.length
      );
      if(attachmentLocalChange) {
        const settled=await settleAttachmentLocalChanges({io,conversationId:ref,change,now});
        actions.push({key:changeKey(change),action:'accept-attachment-local-change'});
        
        
        
        const unresolved=settled?.unresolved_relation_adds||[];
        if(unresolved.length){
          attention.push({
            ...change,
            pending_kind:'conversation',
            key:changeKey(change),
            relation_add_unresolved:unresolved,
            attachments:{
              ...(change.attachments||{}),
              issues:[
                ...(change.attachments?.issues||[]),
                ...unresolved.map((item)=>({
                  type:'attachment-relation-target-missing',
                  attachment_id:item.attachment_id,
                  path:item.path,
                  reason:`附件占位文件指的附件 ${item.attachment_id} 不在附件记录里`,
                })),
              ],
            },
          });
        }
      }
    }
    for(const folder of audit.folder_changes||[]) if(folder.type==='create-mirror'&&folder.automatic){ await createFolderMirror({io,folder:folder.folder,createIn:folder.create_in}); actions.push({key:changeKey(folder),action:'create-mirror'}); }
    return {actions,changed:actions.length>0,attention};
  }

  function pendingFromAudit(audit) {
    const out=[];
    /* ⚠️ 2026-10-07（用户亲定）：**没登记的类型一律不准出现在界面**。
       登记表：`src/management/pending-catalog.js`；契约：`tests/contract-pending-registration.test.cjs`。
       [REV-2026-10-08] 用户 2026-10-08 又把口径**收敛到 3 格**：除了登记，还必须是 `where==='pending'`
       （`where:'auto'` 的同样挡掉 —— 否则"改 auto"就只是登记表上的字，界面上照样冒出来）。 */
    const pendingCatalog=require('../management/pending-catalog');
    const unregistered=[];
    const blockType=(type)=>{ if(type&&!unregistered.includes(type)) unregistered.push(type); };
    const allowPending=(type)=>{
      if(!type) return false;
      if(!pendingCatalog.isRegisteredPendingType(type)){blockType(type);return false;}
      if(pendingCatalog.pendingDisposition(type)!==pendingCatalog.PENDING_WHERE.PENDING){blockType(type);return false;}
      return true;
    };
    for(const change of audit.changes||[]) {
      
      
      if(['move','rename','delete','attachments-detached','gate-archive','gate-unarchive','gate-delete','gate-restore'].includes(change.major?.type)) continue;
      
      
      
      
      
      
      
      const autoAttachment=Boolean(
        change.attachments?.internal_moves?.length || change.attachments?.deletions?.length || change.attachments?.modifications?.length || change.attachments?.additions?.length || change.attachments?.archive_needed?.length || change.attachments?.collection_change?.type==='delete' || change.attachments?.relation_changes?.length
      );
      if(!change.major && autoAttachment) continue;
      if(!auditChangeRequiresUserDecision(change)) continue;
      if(!allowPending(pendingCatalog.pendingTypeOf(change))) continue;
      out.push({...change,pending_kind:'conversation',key:changeKey(change)});
    }
    
    
    
    
    
    if(audit.trusted) for(const folder of audit.folder_changes||[]) if(!(folder.type==='create-mirror'&&folder.automatic)&&allowPending(pendingCatalog.pendingTypeOf(folder))) out.push({...folder,pending_kind:'folder',key:changeKey(folder)});
    else if(folder&&!(folder.type==='create-mirror'&&folder.automatic)){allowPending(pendingCatalog.pendingTypeOf(folder));}
    /* 被挡掉的类型（**没登记** 或 **where:'auto'**）不进界面，单独报出来供诊断 */
    out.unregistered_types=unregistered;
    return out;
  }

  
  
  
  
  
  
  
  
  
  function titleScanTitlesFromIndex(index){
    const out=[],seen=new Set();
    for(const entry of Object.values(index?.conversations||{})){
      if(!entry||entry.local_state==='deleted')continue;
      const title=String(entry.remote_title||entry.title||'').trim();
      if(!title||seen.has(title))continue;
      seen.add(title);out.push(title);
    }
    return out;
  }
  async function refreshTitleCandidateScan(io,index){
    const titles=titleScanTitlesFromIndex(index);
    const previous=await readTitleCandidateState(io);
    const same=previous.titles.length===titles.length&&previous.titles.every((value,position)=>value===titles[position]);
    if(same)return {recorded:false,refreshed_at:previous.refreshed_at,titles};
    const next=await recordTitleCandidateScan(io,{titles,sourceScope:{kind:'manage-check-changes'},completeness:'index-titles',now});
    return {recorded:true,refreshed_at:next.refreshed_at,titles};
  }


  async function buildPairingSnapshot({io,audit,rules,structure,titleScan=null}={}) {
    const scan=titleScan||await readTitleCandidateScan(io);
    const allTitleGroups=titleCandidateGroups(scan.state?.titles||[],rules,{includeIgnored:true});
    const titleCandidates=decorateTitlePairingCandidates(allTitleGroups,rules);
    const localCandidates=audit?.trusted
      ? buildLocalPairingCandidates({paths:audit?.scan?.paths||[],pathEntries:audit?.scan?.path_entries||null,folderSnapshot:audit?.folder_snapshot||null,index:audit?.index||null,axis:effectiveAxis(structure),rulesState:rules})
      : [];
    return {
      checked_at:now(),
      rules_revision:Number(rules?.revision||0),
      local_status:audit?.trusted?'ok':'untrusted',
      local_note:audit?.trusted?'':String(audit?.trust_reason||'本地目录审计不可用，请先重新检查变化'),
      title_status:scan.status,
      title_note:scan.status==='ok'?'':(scan.status==='missing'?'还没有网页标题扫描缓存，请先执行一次检查变化':String(scan.message||'网页标题扫描缓存不可用')),
      title_refreshed_at:scan.state?.refreshed_at||null,
      local_candidates:localCandidates,
      title_candidates:titleCandidates,
    };
  }

  async function pairingCandidates({includeIgnored=false}={}) {
    const snapshot=lastAudit?.pairing_snapshot||null;
    if(!snapshot)return {local_status:'missing',local_note:'请先执行一次检查变化',title_status:'missing',title_note:'请先执行一次检查变化',local_candidates:[],title_candidates:[]};
    if(includeIgnored)return clone(snapshot);
    return {...clone(snapshot),local_candidates:(snapshot.local_candidates||[]).filter((item)=>!item.ignored),title_candidates:(snapshot.title_candidates||[]).filter((item)=>!item.ignored)};
  }

  
  
  
  
  
  
  
  
  
  

  async function checkChanges({ autoSettle = true, mode='deep', onProgress=async()=>{}, conversationUids=null } = {}) {
    const {io}=await requireCurrent(); const settled=[];
    await onProgress({phase:'start',mode,message:mode==='quick'?'正在快速核对本地位置…':'正在深度检查本地变化…'});
    let audit=await auditLocalLibrary(io,{mode,onProgress,conversationUids});
    
    
    
    
    const contentSummary=audit.content_scan==='ran'?audit.content_summary:null;
    const contentNote=contentScanNote(contentSummary);
    
    const bodyNote=String(audit.body_note||'');
    
    
    let attachmentPending=[];
    if(autoSettle){
      const auto=await automaticSettle(io,audit); settled.push(...auto.actions);
      attachmentPending=[...(auto.attention||[])];
      if(auto.changed){
        
        
        
        const recheck=await auditLocalLibrary(io,{mode:'quick',onProgress,conversationUids,scanContent:false});
        audit={...recheck,content_changes:audit.content_changes,content_summary:contentSummary,content_scan:contentSummary?'ran':recheck.content_scan,content_note:contentNote};
      }
    }
    









    const structureForPending = await readLibraryStructure({ io });
    const saveAttachmentsForPending = structureForPending.save_attachments !== false;
    /* [REV-2026-10-08] 用户定：空目录要问的是「**这个空夹是哪条规则的落点**」——
       这件事**跟启用了几个内容层无关**，所以不再按"启用层数 ≥ 2"把那一格藏掉
       （原来的 `oneSidedFolderMeaningful` / `enabledContentLayers` 随之删掉，不留死变量）。
       附件侧读不出来也不再进待处理（改走 auto 记账），所以这里不再按附件项过滤。 */
    const pendingFromLocal=pendingFromAudit(audit);
    const localPending = pendingFromLocal.filter((item) => {
      if (!saveAttachmentsForPending && item?.attachments?.auto_notes?.length) return false;
      return true;
    });
    







    
    
    
    
    
    
    
    
    
    let titleScanNote='';
    let titleScanRecorded=false;
    if(mode==='deep'){
      const refreshed=await refreshTitleCandidateScan(io,audit.index||await loadIndex(io));
      if(refreshed.recorded){
        titleScanRecorded=true;
        titleScanNote=`已按本地索引里的 ${refreshed.titles.length} 条网页标题重扫命名建议`;
      }
    }
    const rulesForPairing=await readRules(io);
    const titleScan=await titleCandidateGroupsFromLibrary(io,rulesForPairing);
    /* [REV-2026-10-08] 用户定（准绳 7）：**表里没有的一律挡掉**。
       `title-candidate` 与附件项原来**绕开登记闸**直接拼进 pending —— 现在统一过 `isRegisteredPendingType`，
       而且只放 `where === 'pending'` 的；挡掉的类型照样记进 `unregistered_types` 供诊断（不许静默吞）。 */
    const pendingCatalogForScan=require('../management/pending-catalog');
    const unregisteredFromScan=[];
    const gatePendingItems=(items)=>{
      const out=[];
      for(const item of Array.isArray(items)?items:[]){
        const type=pendingCatalogForScan.pendingTypeOf(item);
        if(!type||!pendingCatalogForScan.isRegisteredPendingType(type)||pendingCatalogForScan.pendingDisposition(type)!==pendingCatalogForScan.PENDING_WHERE.PENDING){
          if(type&&!unregisteredFromScan.includes(type))unregisteredFromScan.push(type);
          continue;
        }
        out.push(item);
      }
      return out;
    };
    const titlePending=gatePendingItems(titleCandidatePendingItems(titleScan.groups));
    const rawTitleScan=await readTitleCandidateScan(io);
    const pairingSnapshot=await buildPairingSnapshot({io,audit,rules:rulesForPairing,structure:structureForPending,titleScan:rawTitleScan});
    const titleNote=titleScan.status==='corrupt'
      ? '网页标题候选那份记录坏了（已按空处理；再点一次「检查变化」就能补回来）'
      : titleScanNote;
    
    
    
    
    
    
    const pending=[...localPending,...titlePending,...gatePendingItems(attachmentPending)];
    /* ⚠️ 2026-10-06：已经"忽略"的目录不许写进结构基线。
       基线一旦记下它，取消忽略以后它就不再"从没有变成有"，
       detectFolderChanges 再也报不出来 —— 那个文件夹就永远回不到待处理了（死锁）。
       基线只记"你没说过忽略、插件确实认得"的目录。 */
    if(audit.trusted && localPending.length===0){
      const ignoredForBaseline=new Set(normalizeIgnoredFolders(rulesForPairing?.ignored_folders));
      const baseSnapshot=audit.folder_snapshot||{folders:{}};
      const foldersForBaseline=Object.fromEntries(Object.entries(baseSnapshot.folders||{}).filter(([folder])=>!ignoredForBaseline.has(String(folder))));
      await persistResolvedFolderBaseline({io,snapshot:{...baseSnapshot,folders:foldersForBaseline},now});
    }
    





    const libraryNote=contentNote?'':String(audit.library_health_text?.headline||'');
    const completeMessage=`检查完成${pending.length?` · ${pending.length} 项待确认`:''}${contentNote?` · ${contentNote}`:''}${libraryNote?` · ${libraryNote}`:''}${bodyNote?` · ${bodyNote}`:''}${titleNote?` · ${titleNote}`:''}`;
    lastAudit={...audit,requested_mode:mode,pending,settled,checked_at:now(),title_scan_note:titleScanNote,title_scan_recorded:titleScanRecorded,pairing_snapshot:pairingSnapshot,unregistered_types:[...(pendingFromLocal.unregistered_types||[]),...unregisteredFromScan]};
    await onProgress({phase:'complete',mode,message:completeMessage,pending:pending.length,settled:settled.length,content_changes:contentSummary?.changed||0,body_changes:Number(audit.body_scan?.changed?.length||0)});
    return lastAudit;
  }

  async function forceRefresh(conversationIds,{includeAttachments=true,restoreDeletedIds=[],restoreAttachmentIds=[],contentConflictResolutions=null}={}) {
    const library=await requireCurrent(); const index=await loadIndex(library.io); const {rules,resolver}=await classificationResolverForIo(library.io);
    const context=await platformContext({fresh:true}); const inventory=await resolvePlatformInventory(requireRuntimeAdapter(),context);
    const remoteByNative=new Map((inventory.items||[]).map((item)=>[String(item.id||item.conversation_id||''),item]).filter(([id])=>id));
    const remoteRefToNative=new Map();
    for(const nativeId of remoteByNative.keys()){
      const identity=normalizeSourceIdentity(inventory.source_scope||context.source_scope,nativeId);
      remoteRefToNative.set(`source:${identity.source_key}`,nativeId);
    }
    const wantedNative=new Set(); const requestedUids=new Set();
    for(const rawRef of conversationIds||[]){
      const ref=String(rawRef); const uid=resolveConversationUid(index,ref);
      if(uid){
        const entry=index.conversations[uid];
        if(!sourceScopeMatchesEntry(entry,inventory.source_scope||context.source_scope)){
          const e=new Error('所选 对话 来自其他平台 / 账号 / 工作空间，不能用当前来源强制刷新');e.code='source_scope_mismatch';e.conversation_uid=uid;throw e;
        }
        wantedNative.add(String(entry.conversation_id)); requestedUids.add(uid); continue;
      }
      const native=remoteRefToNative.get(ref)||(remoteByNative.has(ref)?ref:null);
      if(native){ wantedNative.add(native); continue; }
      const e=new Error(`无法识别要刷新的 对话：${ref}`);e.code='conversation_selection_unresolved';throw e;
    }
    const selectedItems=[...wantedNative].map((id)=>remoteByNative.get(id)).filter(Boolean);
    if(selectedItems.length!==wantedNative.size){
      const missing=[...wantedNative].filter((id)=>!remoteByNative.has(id)); const e=new Error(`远端清单中找不到 ${missing.length} 个 对话`);e.code='remote_conversation_missing';e.conversation_ids=missing;throw e;
    }
    const selected=selectQuickSyncInventory(inventory,new Set(selectedItems.map((item)=>String(item.id||item.conversation_id||''))));
    const result=await runPlatformNormalSyncOnHandle({rootHandle:library.handle,adapter:requireRuntimeAdapter(),adapterContext:context,inventoryOverride:selected,includeAttachments,classificationResolver:resolver,forceBodyIds:[...wantedNative,...requestedUids],restoreDeletedIds,restoreAttachmentIds,contentConflictResolutions});
    const latest=await loadIndex(library.io); const resolvedUids=new Set(requestedUids);
    for(const native of wantedNative){ const found=findUidBySource(latest,normalizeSourceIdentity(inventory.source_scope||context.source_scope,native)); if(found.uid)resolvedUids.add(found.uid); }
    if(restoreDeletedIds.length) {
      const deleted=await loadDeleted(library.io); for(const id of restoreDeletedIds){const uid=resolveConversationUid(latest,id);if(uid)delete deleted.deleted[uid];delete deleted.deleted[id];} await saveDeleted(library.io,deleted,now);
    }
    return {result,rules,resolved_conversation_uids:[...resolvedUids]};
  }

  async function repairAttachments({ onProgress=async()=>{}, shouldProcessConversation=async()=>true, shouldProcessAttachment=async()=>true, selection=null, asSubtask=false } = {}) {
    const library=await requireCurrent();
    const taskLog=await beginTaskLog(library.io,'attachment-repair',{context:{selection:selection||null,parent_task:asSubtask?'full-save':null}});
    const runtimeTask=asSubtask?null:trackAuthoritativeTask(taskLog,'attachment-repair'); if(runtimeTask)activeAttachmentRepairRuntimeTask=runtimeTask;
    const progress=async(event={})=>{taskLog.event(event);runtimeTask?.recordEvent({type:'progress',...event});await onProgress(event);await cooperativeUiYield();};
    
    
    
    
    let relationRebuild=null;
    // 这一步的成败要一路带到任务状态里去，不能只留一条日志。
    let relationRebuildState=null;
    try{
      
      const repairIndex=await loadIndex(library.io);
      const repairSelectionUids=[...new Set((selection?.conversation_ids||[]).map(String).filter(Boolean))].filter((uid)=>Boolean(resolveConversationUid(repairIndex,uid)));
      relationRebuild=await rebuildAttachmentRelations({io:library.io,adapter:requireRuntimeAdapter(),onProgress:async(event)=>progress({...event,stage:'rebuild-relations'}),...(repairSelectionUids.length?{conversationUids:repairSelectionUids}:{})});
      relationRebuildState={ok:true,message:relationRebuild.message,references_found:relationRebuild.references_found,references_unresolvable:relationRebuild.references_unresolvable||0};
      await progress({phase:'rebuild-relations-done',message:relationRebuild.message,...relationRebuild});
    }catch(error){
      const friendly=errorReport.friendlyError(error);
      relationRebuildState={ok:false,message:friendly,error_code:error?.code||null};
      await progress({phase:'rebuild-relations-failed',message:`附件关系重建没做成：${friendly}`,error_code:error?.code||null});
    }
    
    
    
    
    
    let nameBackfill=null;
    try{
      const backfillRegistry=await optionalJson(library.io,ATTACHMENT_REGISTRY_PATH,null);
      if(backfillRegistry){
        const {backfillAttachmentNames}=require('../assets/attachment-name-backfill');
        
        
        
        nameBackfill=await backfillAttachmentNames({io:library.io,index:await loadIndex(library.io),registry:backfillRegistry,refreshShelves:false,onProgress:async(event)=>progress({...event,stage:'name-backfill'})});
        if(nameBackfill.filled||nameBackfill.conversations_without_raw){
          await progress({phase:'name-backfill-done',message:nameBackfill.message,filled:nameBackfill.filled,no_name_in_source:nameBackfill.no_name_in_source,conversations_without_raw:nameBackfill.conversations_without_raw});
        }
      }
    }catch(error){
      
      await progress({phase:'name-backfill-failed',message:`附件名字回填没做成：${errorReport.friendlyError(error)}`,error_code:error?.code||null});
    }
    
    
    
    let bodyRename=null;
    let renameRegistry=null;
    try{
      renameRegistry=await optionalJson(library.io,ATTACHMENT_REGISTRY_PATH,null);
      if(renameRegistry){
        const {renameDegenerateBodies}=require('../assets/attachment-body-rename');
        bodyRename=await renameDegenerateBodies({io:library.io,registry:renameRegistry,persist:()=>writeJsonVerified(library.io,ATTACHMENT_REGISTRY_PATH,renameRegistry),onProgress:async(event)=>progress({...event,stage:'body-rename'})});
        if(bodyRename.renamed||bodyRename.persist_failed){
          await progress({phase:'body-rename-done',message:bodyRename.message,renamed:bodyRename.renamed,cleaned:bodyRename.cleaned,sha_mismatch:bodyRename.sha_mismatch,bytes_copied:bodyRename.bytes_copied,persist_failed:bodyRename.persist_failed||null});
        }
      }
    }catch(error){
      
      await progress({phase:'body-rename-failed',message:`文件库改名没做成：${errorReport.friendlyError(error)}`,error_code:error?.code||null});
    }
    
    
    
    
    let shelfRefresh=null;
    if((nameBackfill&&nameBackfill.changed_conversations?.length)||(bodyRename&&bodyRename.moved?.length)){
      try{
        const {refreshAllAttachmentViewsForEntry}=require('../library/attachment-view');
        const shelves=new Set(nameBackfill?.changed_conversations||[]);
        const movedContentIds=new Set((bodyRename?.moved||[]).map((item)=>String(item.content_id)));
        if(movedContentIds.size&&renameRegistry){
          for(const relation of Object.values(renameRegistry.relations||{})){
            const asset=renameRegistry.assets?.[relation?.attachment_id];
            if(asset&&movedContentIds.has(String(asset.content_id||''))&&relation?.conversation_uid)shelves.add(String(relation.conversation_uid));
          }
        }
        const shelfIndex=await loadIndex(library.io);
        const shelfRegistry=await optionalJson(library.io,ATTACHMENT_REGISTRY_PATH,null);
        let refreshed=0,failed=0;
        for(const uid of [...shelves].sort()){
          try{const one=await refreshAllAttachmentViewsForEntry({io:library.io,index:shelfIndex,registry:shelfRegistry,conversationUid:uid});if(one.refreshed.length)refreshed+=1;}catch{failed+=1;}
        }
        shelfRefresh={conversations:shelves.size,refreshed,failed};
        await progress({phase:'shelf-refresh-after-rename',message:`附件取回区已按新名字刷新：${refreshed} 个对话${failed?`（${failed} 个没刷成）`:''}`,...shelfRefresh});
      }catch(error){
        await progress({phase:'shelf-refresh-after-rename-failed',message:`附件取回区刷新失败：${errorReport.friendlyError(error)}`,error_code:error?.code||null});
      }
    }
    if(!asSubtask)await writeBackgroundTaskStatus(library.io,'attachment_repair',{task:'attachment-repair',task_id:taskLog.log.task_id,state:'running',blocking:false,user_message:'正在补齐附件',started_at:now(),updated_at:now()});
    const finish=async(response)=>{
      
      const nameBackfillSummary=nameBackfill?{filled:nameBackfill.filled,no_name_in_source:nameBackfill.no_name_in_source,conversations_without_raw:nameBackfill.conversations_without_raw,shelf_refreshed:Number(shelfRefresh?.refreshed||0),message:nameBackfill.message}:null;
      const bodyRenameSummary=bodyRename?{renamed:bodyRename.renamed,cleaned:bodyRename.cleaned,sha_mismatch:bodyRename.sha_mismatch,bytes_copied:bodyRename.bytes_copied,persist_failed:bodyRename.persist_failed||null,shelf_refreshed:Number(shelfRefresh?.refreshed||0),message:bodyRename.message}:null;
      const withNames={...response,name_backfill:nameBackfillSummary,body_rename:bodyRenameSummary,relation_rebuild:relationRebuildState};
      const record={...attachmentRepairTaskStatus(withNames,{now:now()}),task_id:taskLog.log.task_id,name_backfill:nameBackfillSummary,body_rename:bodyRenameSummary};
      if(!asSubtask)await writeBackgroundTaskStatus(library.io,'attachment_repair',record);
      await taskLog.finish(record.state,{summary:{before_saved_assets:record.before_saved,newly_saved_assets:record.newly_saved,after_saved_assets:record.after_saved,missing_assets:record.missing,newly_saved_asset_ids:record.newly_saved_asset_ids,remaining_by_bucket:record.remaining_by_bucket,next_action:record.next_action,conversation_failure_count:record.conversation_failures||0,conversation_failures:record.conversation_failure_details||[],name_backfill:nameBackfillSummary,body_rename:bodyRenameSummary,relation_rebuild:relationRebuildState}});
      if(runtimeTask)finishAuthoritativeTask(runtimeTask,record.state,{result:record,pauseReason:record.pause_reason_code||null});
      if(runtimeTask)activeAttachmentRepairRuntimeTask=null;
      return withNames;
    };
    try {
      const index=await loadIndex(library.io);
      const attachmentRegistry=await optionalJson(library.io,ATTACHMENT_REGISTRY_PATH,null);
      const retiredExamples=await require('../adapters/chatgpt-attachment-discovery').retireLegacySandboxExamples({index,registry:attachmentRegistry,readRaw:path=>optionalJson(library.io,path,null),at:now()});
      if(retiredExamples.length){await writeJsonVerified(library.io,ATTACHMENT_REGISTRY_PATH,attachmentRegistry);await progress({phase:'attachment-reference-reconciliation',retired_examples:retiredExamples});}
      const beforeAttachmentSummary=attachmentSummaryFromIndex(index,{attachmentRegistry});
      const beforeClosure=conversationAttachmentClosure(index,attachmentRegistry);
      const plan=attachmentRepairPlan(index,attachmentRegistry);
      
      
      
      
      
      
      
      
      
      
      
      
      const repairClosure=conversationAttachmentClosure(index,attachmentRegistry);
      const autoRecoverableCount=Number((plan.retry_asset_ids||[]).length)+Number((plan.source_refresh_asset_ids||[]).length);
      const abandonableIds=[...(plan.unavailable_ids||[])].map(String);
      if(autoRecoverableCount===0&&!selection){
        const attachment_summary=attachmentSummaryFromIndex(index,{attachmentRegistry});
        const repair_outcome_breakdown=attachmentRepairOutcomeBreakdown(index,attachmentRegistry,{closure:repairClosure});
        const response={status:'noop',plan,before_attachment_summary:beforeAttachmentSummary,repair_delta:{before_saved_assets:Number(beforeAttachmentSummary.saved||0),newly_saved_assets:[],after_saved_assets:Number(attachment_summary.saved||0),executed_asset_ids:[]},repair_outcome_breakdown,abandonable_asset_ids:abandonableIds,abandonable_count:abandonableIds.length,result:{ok:true,skipped:true,reason:'nothing-auto-recoverable'},attachment_summary,attachment_outcome:deriveAttachmentRepairOutcome({runResult:{ok:true},refreshedSummary:attachment_summary})};
        return finish(response);
      }

      const repairScope=selectAttachmentRepairUids({plan,registry:attachmentRegistry,selection});
      const selectedConversationIds=new Set(repairScope.selected_conversation_ids);
      const selectedAttachmentIds=new Set(repairScope.selected_attachment_ids);
      const targeted=repairScope.targeted;
      const selectedUids=repairScope.selected_uids;
      const beforeAssetIds=new Set(Object.keys(attachmentRegistry?.assets||{}));
      const plannedRepairAssetIds=new Set([...(plan.retry_asset_ids||[]),...(plan.source_refresh_asset_ids||[])].map(String));
      const selectedRelationAssetIds=new Set();
      if(selectedConversationIds.size){
        for(const relation of Object.values(attachmentRegistry?.relations||{})){
          if(relation?.state==='active'&&selectedConversationIds.has(String(relation?.conversation_uid||''))&&relation?.attachment_id)selectedRelationAssetIds.add(String(relation.attachment_id));
        }
      }
      const allowedRepairAssetIds=new Set([...plannedRepairAssetIds].filter((assetId)=>!targeted||selectedAttachmentIds.has(assetId)||selectedRelationAssetIds.has(assetId)));
      const executedRepairAssetIds=new Set();
      if(!selectedUids.length){
        const attachment_summary=attachmentSummaryFromIndex(index,{attachmentRegistry});
        
        
        const explicitEmpty=repairScope.scope_mode==='explicit-empty';
        const response={status:'noop',plan,before_attachment_summary:beforeAttachmentSummary,result:{ok:true,skipped:true,reason:explicitEmpty?'selection-empty':'attachments-already-complete'},attachment_summary,attachment_outcome:deriveAttachmentRepairOutcome({runResult:{ok:true},refreshedSummary:attachment_summary})};
        return finish(response);
      }

      const {rules,resolver}=await classificationResolverForIo(library.io);
      const context=await platformContext({fresh:true});
      
      
      
      
      
      const repairSelectionUids=[...new Set((selection?.conversation_ids||[]).map(String))].filter((uid)=>Boolean(index.conversations?.[uid]));
      let inventory=null;
      if((selection?.conversation_ids||[]).length){
        const natives=repairSelectionUids.map((uid)=>String(index.conversations?.[uid]?.conversation_id||index.conversations?.[uid]?.source_identity?.native_conversation_id||'')).filter(Boolean);
        inventory=buildSelectionInventory({items:natives.map((id)=>({id,source_state:'active'})),sourceScope:context.source_scope,observationKind:'attachment-repair-selection'});
      }else{
        inventory=await resolvePlatformInventory(requireRuntimeAdapter(),context);
      }
      const currentScope=inventory.source_scope||context.source_scope;
      const scopedSummary=attachmentSummaryFromIndex(index,{currentScope,attachmentRegistry});
      const currentScopeIds=new Set([...scopedSummary.current_scope_asset_refresh_ids,...scopedSummary.current_scope_body_refetch_ids].map(String));
      const scopedRepair=selectAttachmentRepairUids({plan,registry:attachmentRegistry,selection,currentScopeIds});
      const currentUids=scopedRepair.current_uids;
      const skippedOtherScope=scopedRepair.skipped_other_scope;
      const remoteByNative=new Map((inventory.items||[]).map((item)=>[String(item.id||item.conversation_id||''),item]).filter(([id])=>id));
      const selectedNative=new Set();
      const forcedBodyRefs=[];
      const skippedUnavailable=[];
      for(const uid of currentUids){
        const entry=index.conversations?.[uid];
        if(!entry)continue;
        const native=String(entry.conversation_id||'');
        if(!native||!remoteByNative.has(native)){skippedUnavailable.push(uid);continue;}
        selectedNative.add(native);
        if(plan.body_refetch_ids.includes(uid)) forcedBodyRefs.push(uid,native);
      }
      if(!selectedNative.size){
        const response={status:'source-unavailable',plan,before_attachment_summary:beforeAttachmentSummary,skipped_other_scope:skippedOtherScope,skipped_unavailable:skippedUnavailable,result:{ok:true,skipped:true,reason:'repair-targets-not-in-current-inventory'},attachment_summary:scopedSummary,attachment_outcome:deriveAttachmentRepairOutcome({runResult:{ok:true},refreshedSummary:scopedSummary})};
        return finish(response);
      }
      const selected=selectQuickSyncInventory(inventory,selectedNative);
      const result=await runPlatformNormalSyncOnHandle({
        rootHandle:library.handle,
        adapter:requireRuntimeAdapter(),
        adapterContext:context,
        inventoryOverride:selected,
        includeAttachments:true,
        classificationResolver:resolver,
        forceBodyIds:[...new Set(forcedBodyRefs)],
        onProgress:progress,
        shouldProcessConversation,
        shouldProcessAttachment:async(info)=>{
          const assetId=String(info?.attachment_id||info?.entity?.entity_id||'');
          const newlyDiscovered=assetId&&!beforeAssetIds.has(assetId);
          if(!newlyDiscovered&&!allowedRepairAssetIds.has(assetId))return SKIP_CONTINUE;
          if(assetId&&executedRepairAssetIds.has(assetId))return SKIP_CONTINUE;
          const decision=normalizeWorkDecision(await shouldProcessAttachment(info),{legacyFalse:'stop',reason:'attachment_gate'});
          if(decision.kind==='process'&&assetId)executedRepairAssetIds.add(assetId);
          return decision;
        },
      });
      const latest=await loadIndex(library.io);
      const latestAttachmentRegistry=await optionalJson(library.io,ATTACHMENT_REGISTRY_PATH,null);
      const attachment_summary=attachmentSummaryFromIndex(latest,{currentScope,attachmentRegistry:latestAttachmentRegistry});
      const afterClosure=conversationAttachmentClosure(latest,latestAttachmentRegistry);
      const afterPlan=attachmentRepairPlan(latest,latestAttachmentRegistry);
      const beforePresent=new Set(beforeClosure.bytes_present_asset_ids||[]);
      const beforeSourceRefresh=new Set(plan.source_refresh_asset_ids||[]);
      const beforePersistent=new Set(plan.manual_only_ids||[]);
      const beforeUnavailable=new Set(plan.unavailable_ids||[]);
      const repair_delta={
        before_saved_assets:Number(beforeAttachmentSummary.saved||0),
        newly_saved_assets:(afterClosure.bytes_present_asset_ids||[]).filter((id)=>!beforePresent.has(id)),
        moved_to_source_refresh:(afterPlan.source_refresh_asset_ids||[]).filter((id)=>!beforeSourceRefresh.has(id)),
        moved_to_persistent:(afterPlan.manual_only_ids||[]).filter((id)=>!beforePersistent.has(id)),
        moved_to_unavailable:(afterPlan.unavailable_ids||[]).filter((id)=>!beforeUnavailable.has(id)),
        after_saved_assets:Number(attachment_summary.saved||0),
        after_missing_assets:Math.max(0,Number(attachment_summary.normalized_entities||attachment_summary.total_assets||0)-Number(attachment_summary.saved||0)),
        executed_asset_ids:[...executedRepairAssetIds].sort(),
      };
      const attachment_outcome=deriveAttachmentRepairOutcome({runResult:result,refreshedSummary:attachment_summary,sourceScope:currentScope});
      




      const repair_outcome_breakdown=attachmentRepairOutcomeBreakdown(latest,latestAttachmentRegistry,{closure:afterClosure});
      const response={status:attachment_outcome.state==='complete'?'repaired':'attention',plan,before_attachment_summary:beforeAttachmentSummary,result,rules,skipped_other_scope:skippedOtherScope,skipped_unavailable:skippedUnavailable,repair_delta,repair_outcome_breakdown,abandonable_asset_ids:abandonableIds,abandonable_count:abandonableIds.length,attachment_summary,attachment_outcome};
      return finish(response);
    } catch(error) {
      const status=Number(error?.details?.status||0)||null;
      const recoverable=status===429||(status>=500&&status<=599)||['network_error','fetch_failed','account_file_library_fetch_failed'].includes(String(error?.code||''));
      const stack=String(error?.stack||'').split('\n').slice(0,12).map((line)=>line.trim()).join(' | ');
      const record={task:'attachment-repair',task_id:taskLog.log.task_id,state:'failed',blocking:false,recoverable,http_status:status,error_code:error?.code||error?.name||'attachment_repair_failed',checkpoint_saved:true,next_action:recoverable?'resume_attachment_repair':'view_attachments',user_message:recoverable?(status?`附件补齐任务暂时中断（HTTP ${status}）；对话 和已保存附件不会回滚。`:'附件补齐任务暂时中断；对话 和已保存附件不会回滚。'):'附件补齐任务没有完成；对话 和已保存附件不会回滚。',detail:error?.message||String(error),updated_at:now()};
      if(!asSubtask)await writeBackgroundTaskStatus(library.io,'attachment_repair',record);
      
      
      await taskLog.finish('failed',{error:{code:record.error_code,status:record.http_status,message:record.detail,stack},summary:{recoverable,failed_because:record.error_code,failed_message:record.detail,next_action:record.next_action,failed_at:stack}});
      if(runtimeTask)finishAuthoritativeTask(runtimeTask,'failed',{result:record,error}); if(runtimeTask)activeAttachmentRepairRuntimeTask=null;
      throw error;
    }
  }

  
  
  
  
  /* ⚠️ 2026-10-08（用户）：**收摊** —— 把"取回出来的真文件"从附件取回区收走，
     只留 占位(.YL) + 清单 + 取回命令 → 回到"预览状态"、空间立刻回来。
     原因：上传给微信/QQ/GPT 是**复制**，取回区永远不空 → 永远不补货 → 真文件一直占库。 */
  async function sweepShelves({ silent = false } = {}) {
    const library = await requireCurrent();
    const { sweepShelves: sweep } = require('../library/shelf-sweep');
    const { attachmentViewPathsForEntry } = require('../library/attachment-view');
    const index = await loadIndex(library.io);
    const registry = await optionalJson(library.io, ATTACHMENT_REGISTRY_PATH, null);
    const directories = [];
    const entries = Object.values(index?.conversations || {});
    for (const entry of entries) {
      for (const dir of attachmentViewPathsForEntry(entry) || []) if (dir) directories.push(dir);
    }
    const report = await sweep({ io: library.io, directories });
    if (!silent && typeof logTaskEvent === 'function') { try { logTaskEvent('shelf-sweep', { removed: report.removed_count, kept: report.kept_count }); } catch { /* 日志失败不影响收摊 */ } }
    return report;
  }

  async function restockAttachmentViews({ silent = false } = {}) {
    const library = await requireCurrent();
    const { restockAttachmentViews: restock, claimBodiesByUniqueName, refreshAllAttachmentViewsForEntry, readTakenNotes, TAKEN_RECORD_PATH } = require('../library/attachment-view');
    const index = await loadIndex(library.io);
    const registry = await optionalJson(library.io, ATTACHMENT_REGISTRY_PATH, null);
    if (!registry) return { checked_conversations: 0, missing_shelves: 0, restocked: [], restocked_count: 0, failed: [], claimed_count: 0 };
    
    
    
    const claim = await claimBodiesByUniqueName({ io: library.io, registry });
    if (claim.claimed_count > 0) {
      await writeJsonVerified(library.io, ATTACHMENT_REGISTRY_PATH, registry);
      const claimedIds = new Set(claim.claimed.map((c) => String(c.attachment_id)));
      const claimedUids = new Set();
      for (const relation of Object.values(registry.relations || {})) {
        if (relation?.state === 'active' && claimedIds.has(String(relation.attachment_id)) && relation.conversation_uid) claimedUids.add(String(relation.conversation_uid));
      }
      for (const uid of [...claimedUids].sort()) {
        
        try { await refreshAllAttachmentViewsForEntry({ io: library.io, conversationUid: uid, registry, index }); } catch {  }
      }
    }
    
    
    
    
    let takenReceipts = [];
    let takenLines = [];
    try {
      const notes = await readTakenNotes({ io: library.io, path: TAKEN_RECORD_PATH });
      takenLines = notes.entries || [];
      
      
      const { collapseTakeReceipts } = require('../library/restock-decision');
      takenReceipts = collapseTakeReceipts(takenLines);
    } catch {  }
    
    
    
    const result = await restock({ io: library.io, index, registry, takenReceipts });
    result.claimed_count = claim.claimed_count;
    result.claimed = claim.claimed;
    result.ambiguous_count = claim.ambiguous_count;
    
    
    
    
    
    if (takenReceipts.length) {
      const norm = (v) => String(v || '').replace(/\\/g, '/').replace(/\/+$/, '');
      const consumed = new Set([
        ...(result.consumed_dirs || []),
        
        ...(result.cancelled_dirs || []),
        ...(result.unknown_view_dirs || []),
      ].map(norm).filter(Boolean));
      if (consumed.size) {
        
        
        
        
        const kept = takenReceipts.filter((parsed) => !consumed.has(norm(parsed?.view_rel || parsed?.view_dir || '')));
        try {
          if (!kept.length) await library.io.remove(TAKEN_RECORD_PATH);
          else await library.io.write(TAKEN_RECORD_PATH, new TextEncoder().encode(kept.map((line) => JSON.stringify(line)).join('\n') + '\n'));
        } catch {  }
      }
    }
    result.claimed_count = claim.claimed_count;
    result.claimed = claim.claimed;
    result.ambiguous_count = claim.ambiguous_count;
    if (result.restocked_count > 0 || claim.claimed_count > 0) {
      const trigger = silent ? 'panel-open' : 'user';
      try {
        const taskLog = await beginTaskLog(library.io, 'attachment-restock', { context: { trigger } });
        await taskLog.finish('succeeded', { summary: { trigger, checked_conversations: result.checked_conversations, missing_shelves: result.missing_shelves, restocked_count: result.restocked_count, 
          
          deferred_count: Number(result.deferred_count || 0), deferred_sample: (result.deferred || [])[0] || null, consumed_dirs_count: (result.consumed_dirs || []).length, claimed_count: claim.claimed_count, claimed: claim.claimed.map((c) => ({ name: c.name, local_path: c.local_path })), ambiguous_count: claim.ambiguous_count, failed_count: (result.failed || []).length } });
      } catch {  }
    }
    return result;
  }

  
  
  
