  let autoLocalCheckInFlight = false;
  async function localCheckState() {
    const library = await getLibrary({ interactive: false });
    if (!library?.io) return { at: null };
    return (await optionalJson(library.io, META_LOCAL_CHECK_PATH, null)) || { at: null };
  }
  async function maybeAutoLocalCheck({ silent = true, intervalMs = null } = {}) {
    const library = await getLibrary({ interactive: false });
    const available = Boolean(library.handle && library.detection?.kind === 'current');
    const state = available ? await localCheckState() : { at: null };
    const writeTaskRunning = Boolean(activeFullSavePauseSignal || activeAttachmentRepairRuntimeTask);
    const decision = autoCheckDecision({
      lastCheckAt: state?.at || null,
      nowMs: Date.now(),
      writeTaskRunning,
      libraryAvailable: available,
      checkInFlight: autoLocalCheckInFlight,
      intervalMs: intervalMs || AUTO_CHECK_INTERVAL_MS,
    });
    if (!decision.run) return { ran: false, ...decision, state };
    if (autoLocalCheckInFlight) return { ran: false, reason: 'check-in-flight', state };
    autoLocalCheckInFlight = true;
    try {
      const audit = await checkChanges({ autoSettle: true, mode: 'quick' });
      const record = {
        at: now(), mode: 'quick', trigger: 'panel-open',
        changes: (audit?.changes || []).length,
        pending: (audit?.pending || []).length,
        settled: (audit?.settled || []).length,
        content_changes: Number(audit?.content_summary?.changed || 0),
        content_scan: audit?.content_scan || null,
        
        body_changes: Number(audit?.body_scan?.changed?.length || 0),
        body_conflicts: Number(audit?.body_scan?.conflicts?.length || 0),
        body_scan_note: String(audit?.body_note || ''),
        trusted: audit?.trusted !== false,
      };
      await writeJson(library.io, META_LOCAL_CHECK_PATH, record);
      return { ran: true, reason: 'ok', age_ms: decision.age_ms, state: record };
    } catch (error) {
      
      const failure = { at: state?.at || null, last_attempt_at: now(), trigger: 'panel-open', error: String(error?.message || error) };
      try { await writeJson(library.io, META_LOCAL_CHECK_PATH, failure); } catch {  }
      return { ran: false, reason: 'check-failed', message: errorReport.friendlyError(error), state: failure };
    } finally { autoLocalCheckInFlight = false; }
  }

  
  
  
