  async function remoteInventory({ maxAgeMs = 0 } = {}) {
    if(maxAgeMs>0&&lastRemoteInventory&&(Date.now()-lastRemoteInventoryAt)<=maxAgeMs)return lastRemoteInventory;
    const context=await platformContext({fresh:true});
    const inventory=await resolvePlatformInventory(requireRuntimeAdapter(),context);
    lastRemoteInventory=inventory; lastRemoteInventoryAt=Date.now();
    return inventory;
  }

  async function catalog({ refreshRemote = false } = {}) {
    const library=await getLibrary({interactive:false});
    const hasCurrent=Boolean(library.handle&&library.detection.kind==='current');
    const index=hasCurrent?await loadIndex(library.io):{schema_version:'2.0',conversations:{},source_map:{}};
    if(!refreshRemote)return catalogRowsFromRemote(index,null,null,library.detection?.kind||'unavailable');
    const remote=await remoteInventory(); const currentScope=remote.source_scope||cachedAdapterContext?.source_scope||inferIndexSourceScope(index);
    return catalogRowsFromRemote(index,remote,currentScope,library.detection?.kind||'unavailable');
  }

  function quickScopeKey(scope='all') {
    if(!scope||scope==='all')return 'all';
    if(typeof scope==='string')return scope;
    try{return JSON.stringify(scope)}catch{return String(scope)}
  }
  function quickSourceScopeKey(sourceScope=null) {
    
    
    return quickSnapshot.quickSourceScopeKey(sourceScope);
  }
  function quickSnapshotBucketKey(sourceScope,scope='all') { return quickSourceScopeKey(sourceScope)+'::'+quickScopeKey(scope); }
  function normalizeQuickSnapshotFile(value) { return quickSnapshot.normalizeQuickSnapshotFile(value); }
  function lightweightQuickItem(item={}) {
    return {id:String(item.id||item.conversation_id||''),title:item.title||'未命名对话',update_time:item.update_time||item.updated_at||null,create_time:item.create_time||item.created_at||null,source_state:item.source_state||'active',project_id:item.project_id||item.projectId||item.gizmo_id||null,project_name:item.project_name||item.project_title||null};
  }
  function remoteInventoryFromBucket(bucket,sourceScope) {
    if(!bucket)return null;
    return {items:(bucket.items||[]).map(lightweightQuickItem),completeness:'partial',scope:'quick-catalog',observation_scope:{kind:'quick-catalog',can_confirm_absence:false},source_scope:sourceScope||bucket.source_scope||null,quick_refresh:{refreshed_at:bucket.refreshed_at||null,stale:Boolean(bucket.stale),error:bucket.error||null,reason:'persisted-snapshot'}};
  }
  
  async function persistProjectNames(io,{sourceScope=null,projects=[]}={}) {
    return quickSnapshot.recordProjectNames({io,sourceScope:sourceScope||cachedAdapterContext?.source_scope||null,projects,now});
  }
  async function readQuickSnapshotFile(io) { return quickSnapshot.readQuickSnapshotFile(io); }
  async function persistQuickSnapshot(io,{sourceScope,scope='all',items=null,refreshedAt=null,stale=false,error=null,projects=null}={}) {
    if(!io||!sourceScope)return null;
    const file=await readQuickSnapshotFile(io);
    const key=quickSnapshotBucketKey(sourceScope,scope);
    if(Array.isArray(items))file.buckets[key]={source_scope:clone(sourceScope),scope:clone(scope),refreshed_at:refreshedAt||now(),stale:Boolean(stale),error:error?clone(error):null,items:items.map(lightweightQuickItem).filter(item=>item.id)};
    if(Array.isArray(projects))file.projects_by_source[quickSourceScopeKey(sourceScope)]={refreshed_at:now(),items:projects.map(item=>({id:String(item.id||item.project_id||''),name:item.name||item.title||String(item.id||item.project_id||''),description:item.description||''})).filter(item=>item.id)};    file.updated_at=now();
    await writeJson(io,QUICK_CATALOG_SNAPSHOT_PATH,file);
    return file;
  }
  async function cachedQuickCatalog(library,index,scope='all') {
    const currentScope=cachedAdapterContext?.source_scope||inferIndexSourceScope(index);
    let remote=null;
    if(library?.handle&&library.detection?.kind==='current'&&currentScope){
      const file=await readQuickSnapshotFile(library.io);
      remote=remoteInventoryFromBucket(file.buckets[quickSnapshotBucketKey(currentScope,scope)],currentScope);
    }
    const mapped=catalogRowsFromRemote(index,remote,currentScope,library?.detection?.kind||'unavailable',{preferSourceRefs:true,scope});
    quickCatalogCache=mapped; quickCatalogCacheScope=quickScopeKey(scope);
    return mapped;
  }
  function remoteItemFromCatalogRow(row={}) {
    return lightweightQuickItem({id:row.conversation_id,title:row.remote_title||row.title,update_time:row.remote_update_time||row.update_time,create_time:row.create_time,source_state:row.remote_source_state||row.source_state,project_id:row.remote_project_id||row.project_id,project_name:row.project_name});
  }
  function selectedCatalogRows(rows,refs) {
    const map=new Map();
    for(const row of rows||[]){for(const key of [row.catalog_ref,row.conversation_uid,row.conversation_id]){if(key!=null&&String(key))map.set(String(key),row)}}
    return [...new Set((refs||[]).map(String).filter(Boolean))].map(ref=>map.get(ref)).filter(Boolean);
  }
  async function mapQuickSnapshot(snapshot,scope='all') {
    const scopeKey=quickScopeKey(scope);
    if(snapshot?.error&&quickCatalogCache&&quickCatalogCacheScope===scopeKey){
      const remote={...(quickCatalogCache.remote||{}),quick_refresh:{refreshed_at:snapshot.refreshedAt||null,stale:true,error:snapshot.error,reason:snapshot.reason||null}};
      return {...quickCatalogCache,remote};
    }
    const library=await getLibrary({interactive:false});
    const hasCurrent=Boolean(library.handle&&library.detection.kind==='current');
    const index=hasCurrent?await loadIndex(library.io):{schema_version:'2.0',conversations:{},source_map:{}};
    const context=await platformContext();
    const remote=quickInventoryFromSnapshot(snapshot,context.source_scope);
    const mapped=catalogRowsFromRemote(index,remote,context.source_scope,library.detection?.kind||'unavailable',{preferSourceRefs:true,scope});
    if(hasCurrent&&!snapshot?.error)await persistQuickSnapshot(library.io,{sourceScope:context.source_scope,scope,items:remote.items,refreshedAt:snapshot?.refreshedAt||now(),stale:Boolean(snapshot?.stale),error:snapshot?.error||null});
    quickCatalogCache=mapped; quickCatalogCacheScope=scopeKey;
    return mapped;
  }
  async function openQuickCatalog({scope='all'}={}) {
    const library=await getLibrary({interactive:false});
    const hasCurrent=Boolean(library.handle&&library.detection.kind==='current');
    const index=hasCurrent?await loadIndex(library.io):{schema_version:'2.0',conversations:{},source_map:{}};
    const cached=quickCatalogCache&&quickCatalogCacheScope===quickScopeKey(scope)?quickCatalogCache:await cachedQuickCatalog(library,index,scope);
    const opened=getQuickCandidateSource().open({scope});
    const refreshPromise=opened.refreshPromise.then((snap)=>mapQuickSnapshot(snap,scope));
    return {cached,refreshPromise};
  }

  async function refreshQuickCatalog({reason='manual',scope='all',force=false,maxPages=undefined}={}) {
    const snap=await getQuickCandidateSource().refresh({reason,scope,force,maxPages});
    return mapQuickSnapshot(snap,scope);
  }

  async function listQuickProjects({force=false}={}) {
    const library=await getLibrary({interactive:false});
    const hasCurrent=Boolean(library.handle&&library.detection.kind==='current');
    const index=hasCurrent?await loadIndex(library.io):{schema_version:'2.0',conversations:{}};
    const inferred=cachedAdapterContext?.source_scope||inferIndexSourceScope(index);
    if(hasCurrent&&inferred&&!force){
      const file=await readQuickSnapshotFile(library.io);
      const cached=file.projects_by_source[quickSourceScopeKey(inferred)]?.items||[];
      if(cached.length)return clone(cached);
    }
    const projects=await getQuickCandidateSource().listProjects({force});
    if(hasCurrent&&projects.length){const context=await platformContext();await persistProjectNames(library.io,{sourceScope:context.source_scope,projects});}
    if(projects.length)return projects;
    /* ⚠️ 2026-10-07：取不到远端项目清单时，用**索引里的项目身份**兜底
       （身份唯一来源 = `project_memberships`）。
       以前这里直接返回空 → 提取页的项目下拉是空的（真机现场：「全部项目」里什么都没有）。 */
    const seenProjects=new Map();
    for(const entry of Object.values(index?.conversations||{})){
      if(!entry||entry.local_state==='deleted')continue;
      const identity=projectIdentityOfEntry(entry);
      if(!identity.id&&!identity.name)continue;
      const key=identity.id||('name:'+identity.name);
      if(!seenProjects.has(key))seenProjects.set(key,{id:identity.id||identity.name,name:identity.name||identity.id,title:identity.name||identity.id});
    }
    if(seenProjects.size)return [...seenProjects.values()];
    return projects;
  }

  async function syncSelected(conversationIds,{includeAttachments=false,force=false,scope='all',onProgress=async()=>{}}={}) {
    const progress=async(event={})=>{await onProgress(event);await cooperativeUiYield();};
    const library=await requireCurrent({interactive:true});
    const index=await loadIndex(library.io);
    const catalog=quickCatalogCache&&quickCatalogCacheScope===quickScopeKey(scope)?quickCatalogCache:await cachedQuickCatalog(library,index,scope);
    const selectedRows=selectedCatalogRows(catalog.items||[],conversationIds);
    
    
    
    let plan=planQuickSelection(catalog.items||[],conversationIds,{includeAttachments,assumeNativeForUnknown:true});
    const resolvedUids=new Set();
    const restoreDeletedRefs=new Set();
    for(const ref of conversationIds||[]){const uid=resolveConversationUid(index,String(ref));if(uid)resolvedUids.add(uid)}
    for(const row of selectedRows){if(row.conversation_uid)resolvedUids.add(String(row.conversation_uid));if(row.recoverable_remote_present){if(row.conversation_uid)restoreDeletedRefs.add(String(row.conversation_uid));if(row.conversation_id)restoreDeletedRefs.add(String(row.conversation_id));}}
    if(plan.unresolved_refs.length){
      const unresolved=plan.unresolved_refs.filter(ref=>!resolveConversationUid(index,ref));
      if(unresolved.length){const e=new Error(`无法识别要导出的 对话：${unresolved[0]}`);e.code='conversation_selection_unresolved';throw e;}
    }
    const forceRemote=force?selectedRows.filter(row=>row.remote===true&&row.conversation_id).map(row=>String(row.conversation_id)):[];
    const nativeToSync=new Set([...plan.network_native_ids,...forceRemote]);
    let syncResult={ok:true,skipped:true,reason:'selected-items-ready-local',quick_plan:plan};
    if(nativeToSync.size){
      const context=await platformContext({fresh:true});
      
      
      const rowByNative=new Map(selectedRows.filter(row=>row.remote===true).map(row=>[String(row.conversation_id||''),row]));
      const items=[...nativeToSync].map(native=>{const row=rowByNative.get(String(native));return row?remoteItemFromCatalogRow(row):{id:String(native),source_state:'active'};});
      
      
      const inventory=buildSelectionInventory({items,sourceScope:context.source_scope,observationKind:'manual-or-selected-ids'});
      const {resolver}=await classificationResolverForIo(library.io);
      const forced=[...new Set([...nativeToSync,...restoreDeletedRefs])];
      syncResult=await runPlatformNormalSyncOnHandle({rootHandle:library.handle,adapter:requireRuntimeAdapter(),adapterContext:context,inventoryOverride:inventory,includeAttachments,classificationResolver:resolver,forceBodyIds:forced,restoreDeletedIds:[...restoreDeletedRefs],onProgress:progress});
      const latest=await loadIndex(library.io);
      for(const native of nativeToSync){const found=findUidBySource(latest,normalizeSourceIdentity(context.source_scope,native));if(found.uid)resolvedUids.add(found.uid)}
    }
    const latest=await loadIndex(library.io);
    for(const ref of conversationIds||[]){const uid=resolveConversationUid(latest,String(ref));if(uid)resolvedUids.add(uid)}
    markAcquisitionOrigin(latest,[...resolvedUids],'quick-extraction',now());
    await saveIndex(library.io,latest,now);
    return {result:syncResult,resolved_conversation_uids:[...resolvedUids],quick_plan:plan};
  }

  
  
  function conversationIdFromInput(value) {
    const text=String(value||'').trim();
    if(!text||! /^https?:\/\//i.test(text))return null;
    try {
      const adapter=requireRuntimeAdapter();
      if(!adapter||typeof adapter.getConversationId!=='function')return null;
      const id=adapter.getConversationId(text);
      return id?String(id):null;
    } catch { return null; }
  }

