  async function contentScopeInfo(conversationIds=[]) {
    const refs=[...new Set((conversationIds||[]).map(String))];
    const library=await getLibrary({interactive:false});
    if(!library.handle||library.detection.kind!=='current')return {items:refs.map((ref)=>({ref,conversation_uid:null,title:null,has_human:false,human_count:0})),affected:[]};
    const index=await loadIndex(library.io); const items=[];
    for(const ref of refs){
      const uid=resolveConversationUid(index,ref); const entry=uid?index.conversations?.[uid]:null;
      if(!entry){items.push({ref,conversation_uid:null,title:null,has_human:false,human_count:0});continue;}
      const loaded=await loadContentState(library.io,entry);
      const count=Array.isArray(loaded?.value?.human_contributions)?loaded.value.human_contributions.length:0;
      items.push({ref,conversation_uid:uid,title:entry.title||'未命名对话',has_human:count>0,human_count:count});
    }
    return {items,affected:items.filter((item)=>item.has_human)};
  }

