  async function withTaskLog(library, taskType, context, run) {
    const task = await beginTaskLog(library.io, taskType, { trigger: 'user', context });
    try {
      const result = await run(task);
      const ok = result?.saved > 0 || result?.marked_count > 0 || result?.count > 0 || result?.reviewed > 0;
      await task.finish(ok ? 'succeeded' : 'succeeded_with_warnings', {
        summary: {
          reviewed: result?.reviewed ?? null, saved: result?.saved ?? null, still_unavailable: result?.still_unavailable ?? null,
          marked: result?.marked_count ?? null, count: result?.count ?? null, path: result?.path ?? null,
          message: result?.message || null,
        },
      });
      return result;
    } catch (error) {
      await task.finish('failed', { error: { message: error?.message || String(error), code: error?.code || null } });
      throw error;
    }
  }

  
  
  
  
  
  

  







  async function saveLayerLayout({ order = null, confirm = false, onProgress = null } = {}) {
    const library = await requireCurrent();
    const { io } = library;
    const { readLibraryStructure, writeLibraryStructure } = require('../library/library-structure');
    const { planLayerLayoutForLibrary, remapLayerPaths } = require('../library/layer-layout-plan');
    const { applyLayerRename, filesUnder } = require('../library/layer-layout-apply');
    const structure = await readLibraryStructure({ io });
    const plan = await planLayerLayoutForLibrary({
      io, structure, toOrder: order, attachmentsWanted: structure.save_attachments !== false,
    });
    if (!plan.checked) {
      throw Object.assign(new Error(plan.note || '读不到盘上现在有哪些目录，先不动'), { code: 'layer_layout_unknown' });
    }
    if (!confirm) {
      return { applied: false, changed: plan.changed, text: plan.text, plan: plan.plan, to_order: plan.to_order, dirs: plan.dirs };
    }
    
    const nextStructure = await writeLibraryStructure({ io, structure: { ...structure, layer_order: plan.to_order }, now });
    
    
    
    require('../library/layer-numbering').setCurrentOrder(plan.to_order);
    
    const jobs = [
      ...plan.plan.rename.map((x) => ({ ...x, what: '改名' })),
      ...plan.plan.thaw.map((x) => ({ ...x, what: '解冻' })),
      ...plan.plan.freeze.map((x) => ({ ...x, what: '冻结' })),
    ];
    const allPaths = typeof io.listPaths === 'function' ? await io.listPaths() : [];
    const results = [];
    for (const job of jobs) {
      const outcome = await applyLayerRename({
        io,
        from: job.from,
        to: job.to,
        files: filesUnder(allPaths, job.from),
        onProgress: async (event) => { if (typeof onProgress === 'function') await onProgress({ ...event, layer: job.layer, what: job.what }); },
        commitLedger: async () => {
          const index = await loadIndex(io);
          const remapped = remapLayerPaths(index, { from: job.from, to: job.to });
          await saveIndex(io, remapped.value, now);
          const registryValue = await optionalJson(io, ATTACHMENT_REGISTRY_PATH, null);
          if (registryValue) {
            const remappedRegistry = remapLayerPaths(registryValue, { from: job.from, to: job.to });
            if (remappedRegistry.changed) await writeJsonVerified(io, ATTACHMENT_REGISTRY_PATH, remappedRegistry.value);
          }
        },
      });
      results.push({ layer: job.layer, what: job.what, from: job.from, to: job.to, ok: outcome.ok, moved: outcome.moved, failed: outcome.failed.length, skipped: outcome.skipped.length });
      if (!outcome.ok) break;   
    }
    









    let catchup = [];
    const thawedKinds = [...new Set((plan.plan.thaw || []).map((job) => String(job.layer || '')))].filter(Boolean);
    if (thawedKinds.length && !results.some((item) => !item.ok)) {
      const { catchUpLayerFiles, layerCatchupMessage } = require('../library/layer-catchup');
      const { conversationAssetPathsForEntry, currentLayerDirs } = require('../sync/path-plan');
      const indexNow = await loadIndex(io);
      for (const layer of thawedKinds) {
        const outcome = await catchUpLayerFiles({
          io, index: indexNow, kind: layer,
          persist: () => writeJsonVerified(io, INDEX_PATH, indexNow),
          onProgress: async (event) => { if (typeof onProgress === 'function') await onProgress(event); },
          conversationAssetPathsForEntry,
        });
        const label = (currentLayerDirs()[layer] || layer);
        const message = layerCatchupMessage({ kind: layer, label, planned: outcome.planned, moved: outcome.moved, skipped: outcome.skipped });
        catchup.push({ layer, ...outcome, message });
      }
    }
    return { applied: true, structure: nextStructure, results, catchup, changed: plan.changed, text: plan.text, dirs: plan.dirs };
  }

  async function unavailableAttachments() {
    const library = await getLibrary({ interactive: false });
    if (!library.handle || library.detection.kind !== 'current') return { rows: [], total: 0, by_bucket: {}, unresolved: 0, abandoned: 0 };
    const [index, registryValue] = await Promise.all([loadIndex(library.io), optionalJson(library.io, ATTACHMENT_REGISTRY_PATH, null)]);
    const { listUnavailableAttachments } = require('../assets/attachment-review');
    return listUnavailableAttachments({ index, registry: registryValue ? normalizeAttachmentRegistry(registryValue) : null });
  }

  // 附件记录会在“放弃 / 撤销放弃”等动作里单独变化，但 Conversation 索引并不会跟着改。
  // panel summary 原来只拿 index.stat 当缓存钥匙，所以这类动作会出现“账已经改了，完整性 UI 还停在旧数字”。
  async function refreshAttachmentSummaryCacheFromRegistry(library, registry, index = null) {
    index = index || await loadIndex(library.io);
    const attachmentSummary = attachmentSummaryFromIndex(index, {
      currentScope: cachedAdapterContext?.source_scope || null, attachmentRegistry: registry,
    });
    // The registry is already verified. Cache failure must be visible, not a fake failed mutation.
    try { await persistPanelSummary(library.io, { attachmentSummary }); }
    catch (error) { attachmentSummary.cache_warning = String(error?.message || error); }
    return attachmentSummary;
  }

