  async function inspectManualClaim({ attachmentId = '', fileName = '', sizeBytes = null, bytes = null } = {}) {
    const { manualClaimRejection, inspectManualAttachmentClaim } = require('../assets/manual-claim');
    const rejection = manualClaimRejection({ bytes, fileName });
    if (rejection) { const e = new Error(rejection); e.code = 'manual_claim_rejected'; throw e; }
    if (!attachmentId) { const e = new Error('要交给哪一件还没定（不许替你猜）'); e.code = 'manual_claim_target_required'; throw e; }
    const library = await requireCurrent({ interactive: false });
    const registryValue = await optionalJson(library.io, ATTACHMENT_REGISTRY_PATH, null);
    if (!registryValue) throw new Error('附件记录读不出来');
    const registry = normalizeAttachmentRegistry(registryValue);
    const asset = registry.assets?.[String(attachmentId)];
    if (!asset) { const e = new Error('附件记录里没有这一件附件'); e.code = 'manual_claim_unknown_attachment'; throw e; }
    const { sha256Hex } = require('../sync/transaction');
    const selectedSha256 = await sha256Hex(bytes);
    const contentBefore = asset.content_id ? (registry.contents?.[asset.content_id] || null) : null;
    return inspectManualAttachmentClaim({ asset, content: contentBefore, fileName, sizeBytes, selectedSha256 });
  }
  async function registerManualAttachment({ attachmentId = '', bytes = null, fileName = '', sizeBytes = null, userConfirmed = false } = {}) {
    const library = await requireCurrent();
    return withTaskLog(library, 'attachment-register', { attachment_id: String(attachmentId || ''), file_name: String(fileName || '') }, async (task) => {
      const { manualClaimRejection, inspectManualAttachmentClaim, applyManualClaimTrace } = require('../assets/manual-claim');
      const rejection = manualClaimRejection({ bytes, fileName });
      if (rejection) { const e = new Error(rejection); e.code = 'manual_claim_rejected'; throw e; }
      if (!attachmentId) { const e = new Error('要交给哪一件还没定（不许替你猜）'); e.code = 'manual_claim_target_required'; throw e; }
      const registryValue = await optionalJson(library.io, ATTACHMENT_REGISTRY_PATH, null);
      if (!registryValue) throw new Error('附件记录读不出来');
      const registry = normalizeAttachmentRegistry(registryValue);
      const asset = registry.assets?.[String(attachmentId)];
      if (!asset) { const e = new Error('附件记录里没有这一件附件'); e.code = 'manual_claim_unknown_attachment'; throw e; }
      






      const { sha256Hex } = require('../sync/transaction');
      const selectedSha256 = await sha256Hex(bytes);
      const contentBefore = asset.content_id ? (registry.contents?.[asset.content_id] || null) : null;
      const inspection = inspectManualAttachmentClaim({ asset, content: contentBefore, fileName, sizeBytes, selectedSha256 });
      if (inspection.verification_level === 'mismatch' && !userConfirmed) {
        const error = new Error(`这一份跟附件记录不一致：${inspection.reasons.join('；')}。请确认是不是就要用这一份（你确认了才会收下）。`);
        error.code = 'manual_claim_mismatch';
        error.inspection = inspection;
        throw error;
      }
      
      
      const preferred = String(asset.original_filename || asset.aliases?.[0] || fileName || 'attachment');
      await ingestManualAttachmentBytes({ io: library.io, registry, attachmentId: String(attachmentId), bytes, preferredFilename: preferred, now });
      if (fileName && String(fileName) !== preferred) {
        asset.aliases = [...new Set([...(asset.aliases || []), String(fileName)])];
      }
      


      applyManualClaimTrace(asset, { inspection, userConfirmed: Boolean(userConfirmed), at: now() });
      await writeJsonVerified(library.io, ATTACHMENT_REGISTRY_PATH, registry);
      
      
      
      
      
      
      const link = require('../assets/manual-claim').conversationUidForAttachment({ registry, attachmentId: String(attachmentId) });
      const conversationUid = link.conversation_uid;
      let shelfRefreshed = false;
      let relationNote = conversationUid
        ? (link.reason === 'relation-recycled' ? '附件引用已移除。建立取回入口不会自动恢复引用。' : null)
        : '这件在附件记录里**确实没有**关联到任何对话（它拿回来了，但进不了任何一条对话的附件取回区）';
      if (conversationUid) {
        try {
          const index = await loadIndex(library.io);
          const scanned = typeof library.io.listPaths === 'function' ? await library.io.listPaths() : null;
          await refreshAllAttachmentViewsForEntry({ io: library.io, index, registry, conversationUid, existingPaths: scanned });
          shelfRefreshed = true;
        } catch (error) { relationNote = `附件取回区更新失败：${errorReport.friendlyError(error)}`; }
      }
      

      const verificationNote = inspection.verification_level === 'exact'
        ? '内容校验值对得上（就是同一份字节）'
        : inspection.verification_level === 'compatible'
          ? '名字和大小对得上，但附件记录里没有原始内容校验值，证明不了是同一份字节'
          : inspection.verification_level === 'mismatch'
            ? `⚠️ 与附件记录不一致（你已确认要用这一份）：${inspection.reasons.join('；')}`
            : '附件记录里没有可比的校验信息，这次验不了（记录已经留下）';
      const message = `已收下《${fileName}》并按附件记录里的名字存成 ${preferred}（这件归库管了）`
        + (shelfRefreshed ? '，附件取回区已经补上它的附件占位文件' : '')
        + `；核对结果：${verificationNote}`
        + (relationNote ? `；⚠️ ${relationNote}` : '');
      task.event({ type: 'manual_claim_result', stage: 'register', status: shelfRefreshed ? 'complete' : 'warn', attachment_id: String(attachmentId), stored_as: preferred, shelf_refreshed: shelfRefreshed, verification_level: inspection.verification_level, user_confirmed: Boolean(userConfirmed), message });
      return { attachment_id: String(attachmentId), stored_as: preferred, shelf_refreshed: shelfRefreshed, note: relationNote, verification_level: inspection.verification_level, user_confirmed: Boolean(userConfirmed), inspection, message };
    });
  }

  
  
  
  async function libraryStructureState() {
    const library = await getLibrary({ interactive: false });
    if (!library.handle || library.detection?.kind !== 'current') return { available: false, axis: 'classification' };
    const structure = await readLibraryStructure({ io: library.io });
    
    
    const { effectiveAxis } = require('../library/library-structure');
    const effective = effectiveAxis(structure);
    setConfirmedAxis(effective);
    /* ⚠️ 2026-10-06 E 批：把“正在换轴”暴露给界面。
       滑块只表达“已确认主轴”（structure.axis），
       换轴进行中另写一句话 —— 不再让滑块提前跳到目标、看着“点不动”。 */
    const { readAxisSwitchMarker } = require('../library/axis-flip');
    const inFlight = await readAxisSwitchMarker({ io: library.io }).catch(() => null);
    return { available: true, ...structure, effective_axis: effective, axis_switch_in_flight: inFlight };
  }

  async function setLibraryAxis({ axis = 'classification' } = {}) {
    const library = await requireCurrent();
    return withTaskLog(library, 'library-axis', { axis: String(axis) }, async (task) => {
      const before = await readLibraryStructure({ io: library.io });
      const change = axisChangeNeeded(before, axis);
      if (!change.needed) {
        const same = '主视图没变，什么都不用动';
        task.event({ type: 'axis_unchanged', status: 'complete', axis: change.from, message: same });
        return { changed: false, axis: change.from, message: same };
      }
      
      
      
      
      /* ⚠️ 2026-10-06 D 批 + [REV-2026-10-08]：**轴身份只有一个来源** —— `library-structure.json` 的 `axis`。
         `pending_axis` 这个字段连同它的优先级**整条删掉**（准绳 8）：不再写、不再读、不再归一化。
         换轴期间的进度由轴开关标记（`axis-flip` 的 marker）表达；滑块只表达"现在是哪条轴"。 */
      const { readAxisSwitchMarker: _readMarker, writeAxisSwitchMarker, clearAxisSwitchMarker } = require('../library/axis-flip');
      await writeAxisSwitchMarker({ io: library.io, from: change.from, to: change.to, startedAt: now() });
      setConfirmedAxis(change.to);
      const index = await loadIndex(library.io);
      
      const { AXIS_PROJECT, outsideHasNaming, setOutsideHasNaming, indexHasCategories, setCategoriesInUse } = require('../sync/path-plan');
      setOutsideHasNaming(change.to === AXIS_PROJECT && outsideHasNaming(index));
      setCategoriesInUse(indexHasCategories(index));
      const projectNameOf = (entry) => String((membershipOf(entry) || {}).name || '');
      const migration = await migrateAllToAxis({
        io: library.io,
        index,
        axis: change.to,
        projectNameOf,
        persistIndex: async (value) => { await saveIndex(library.io, value, now); },
        onProgress: async (event) => { await task.event({ type: 'axis_progress', message: event.message }); },
        now,
      });
      
      let verification = verifyAxisMigration({ index, axis: change.to, projectNameOf });
      /* 换轴是**本地**操作（复制 + 删源），不是网络操作。第一遍因为"目标已存在/源已不在"
         跳过的东西，第二遍通常就能收干净 —— 所以这里自动补一轮，而不是让用户"再点一次"。 */
      let secondPass = null;
      if (!verification.complete) {
        await task.event({ type: 'axis_second_pass', status: 'running', message: '还有没搬完的，自动再补一轮…' });
        secondPass = await migrateAllToAxis({
          io: library.io, index, axis: change.to, projectNameOf,
          persistIndex: async (value) => { await saveIndex(library.io, value, now); },
          onProgress: async (event) => { await task.event({ type: 'axis_progress', message: event.message }); },
          now,
        });
        verification = verifyAxisMigration({ index, axis: change.to, projectNameOf });
      }
      const totalMoved = migration.moved + (secondPass?.moved || 0);
      const totalSkipped = migration.skipped + (secondPass?.skipped || 0);

      const label = change.to === 'project' ? '项目在外、自命名收进 10_自命名' : '自命名在外、项目收进 10_项目';
      if (verification.complete) {
        /* ⚠️ 2026-10-06：搬完还要**收尾**。以前只改 structure + 报"已换成"，
           旧主轴那棵树（如 10_项目/）原样留着 —— 用户点进资料库照样看见旧结构，
           下次审计还会把它读成"新目录/多副本"。这里做一次"已确认搬走才删"的清扫：
           只删同一份内容在新位置确实存在的文件，有一处对不上就整棵树不动。 */
        const retired = await retireAxisRoots({ io: library.io, index, canonicalRoots: change.to === 'project' ? ['10_项目'] : ['10_自命名'] }).catch(() => null);

        /* ⚠️ 2026-10-08（用户同意；压力测试证据）：搬完还要**对账自愈** ——
           半途中断留下的脏起点（旧副本 + 新副本并存、索引与盘不符、残留 in-flight 标记）
           靠 retireAxisRoots 的两道护符是清不掉的（它只在"别处有逐字节孪生"时才删，索引错位就够不着）。
           这一步：算规范位置 → 逐字节相同的删旧副本并把索引改指真身 → 逐字节不同的两份都留只报告
           → 收空目录 → 清残留标记。 */
        const { reconcileLibrary } = require('../library/library-reconcile');
        const reconcile = await reconcileLibrary({ io: library.io, index, axis: change.to, now }).catch((error) => ({ failed: [{ reason: String(error && error.message) }] }));
        await clearAxisSwitchMarker({ io: library.io });
        const committed = await writeLibraryStructure({ io: library.io, structure: { ...before, axis: change.to, migrated_at: now(), migration: { conversations: migration.conversations, moved: totalMoved, skipped: totalSkipped, verified: true, second_pass: Boolean(secondPass), retired_axis_files: retired?.removed_files || 0, retired_axis_dirs: retired?.removed_dirs || 0, retired_axis_kept: (retired?.kept || []).length } }, now });
        setConfirmedAxis(change.to);
        const message = `主视图已换成「${label}」：搬了 ${migration.conversations} 条对话 / ${totalMoved} 个文件`
          + (secondPass?.moved ? `（补了一轮 ${secondPass.moved} 个）` : '')
          + (totalSkipped ? `；${totalSkipped} 处没搬成（一律原样留着，明细在任务日志里）` : '')
          + (retired?.removed_files ? `；清掉 ${retired.removed_files} 个已确认搬走的旧副本` : '')
          + (retired?.kept?.length ? `；还有 ${retired.kept.length} 处对不上（原样留着，没删）` : '');
        task.event({ type: 'axis_changed', status: (totalSkipped || retired?.kept?.length) ? 'warn' : 'complete', from: change.from, to: change.to, message, skipped: totalSkipped, retired, failures: migration.failures.slice(0, 20), verified: true });
        return { changed: true, axis: change.to, migration, verification, structure: committed, retired, message };
      }
      
      // 两句都别写 markdown 粗体 —— 状态栏是纯文本，星号会照原样显示。
      // 这里**保留标记文件**：下次打开发现标记还在，就接着收尾（不再要用户"再点一次"）。
      const message = `主视图要换成「${label}」，补了一轮还剩 ${verification.remaining_count} 处（${verification.remaining_conversations} 条对话）`
        + `。本轮共搬了 ${migration.conversations} 条 / ${totalMoved} 个文件；没搬成的一律原样留着，下次打开会接着收尾。`;
      task.event({ type: 'axis_incomplete', status: 'warn', from: change.from, to: change.to, message, remaining: verification.remaining_count, failures: migration.failures.slice(0, 20) });
      return { changed: false, pending: true, axis: change.from, migration, verification, message };
    });
  }

  
  
  
  
  
