    const output=await getExtractEntry({interactive:false});
    if(!library.handle||library.detection.kind!=='current'||!output.handle)return {available:Boolean(output.handle),foreign_names:[],plugin_owned_names:[]};
    const previous=(await optionalJson(library.io,OUTPUT_ENTRY_STATE_PATH,{items:[]}))?.items||[];
    const classified=await classifyShortcutContent(output.handle,previous);
