  async function extract(conversationIds,optionsInput,{scene='local-extract',quickScope='all',onProgress=async()=>{}}={}) {
    /* [REV-2026-10-07] 用户已经选过「不保留」就不该再问：`history_retention` **以库里存的那份为准**，
     不许被请求里的旧副本盖掉（每轮的选择走 `keep_history`，与这条设置是两回事）。 */
const storedOutput=await readOutputPreferences();
    const options={...storedOutput,...optionsInput,history_retention:storedOutput.history_retention};
    if(!options.configured){const e=new Error('第一次提取需要先完成输出设置');e.code='output_preferences_required';throw e;}
    const {io}=await requireCurrent();
    const output=await getExtractEntry({interactive:false});
    if(!output.handle){const e=new Error('尚未选择提取入口');e.code='extract_entry_required';throw e;}
    const previous=(await optionalJson(io,OUTPUT_ENTRY_STATE_PATH,{items:[]}))?.items||[];
    const shortcut=await prepareShortcutForNewBatch({entryHandle:output.handle,previousEntryItems:previous,io,action:options.shortcut_foreign_action||null,now:()=>new Date(now())});
    if(shortcut.requires_user_decision){const e=new Error('提取入口里有你自己放入的文件，需要先决定如何处理');e.code='shortcut_foreign_decision_required';e.foreign_names=shortcut.foreign_names;throw e;}
    if(shortcut.canceled){const e=new Error('已取消本次提取');e.code='extraction_canceled';throw e;}
    const index=await loadIndex(io);
    const selectionSource=selectionSourceForScene({scene,index,resolveUid:resolveConversationUid,candidateSource:getQuickCandidateSource(),syncSelected,quickScope});
    const retention=resolveHistoryRetentionDecision(options.history_retention);
    if(retention.requires_user_decision&&typeof options.keep_history!=='boolean'){const e=new Error('这次是否保留提取历史还没有确认');e.code='history_retention_decision_required';throw e;}
    const keepHistory=retention.requires_user_decision?options.keep_history:retention.keep_history;
    const attachmentRegistry=await optionalJson(io,ATTACHMENT_REGISTRY_PATH,null);
    const journal=await beginTaskLog(io,'extraction',{context:{scene,conversation_ids:conversationIds}});
    let meta=null;
    try {
      meta=await runExtraction({io,selectionSource,selectedIds:conversationIds,options,attachmentRegistry,entryHandle:output.handle,previousEntryItems:previous,keepHistory,now:()=>new Date(now()),onProgress});
      await writeJsonVerified(io,OUTPUT_ENTRY_STATE_PATH,{
        updated_at:now(),items:meta.entry_tracking_items||meta.entry_items||[],
        current_items:meta.entry_items||[],cleanup_pending:meta.entry_cleanup?.retry_items||[],
        cleanup_failures:meta.entry_cleanup?.failures||[],last_extraction_id:meta.id,
      });
      journal.event({type:'extraction_result',stage:'cleanup-old',entry_cleanup:meta.entry_cleanup});
      await journal.finish(meta.warnings?.length?'succeeded_with_warnings':'succeeded',{
        summary:{extraction_id:meta.id,file_count:meta.file_count,entry_items:meta.entry_items,entry_cleanup:meta.entry_cleanup,warnings:meta.warnings},
      });
      if (!journal.writable) meta.warnings.push({code:'extraction_log_unavailable',message:'新批已生成，入口记录已保存，但本次任务日志未写入；请保留完成页提示。'});
      return meta;
    } catch (error) {
      if (meta) {
        const wrapped=new Error(error?.message||String(error));
        wrapped.code='shortcut_result_record_failed';wrapped.cause=error;
        wrapped.affected_paths=(meta.entry_tracking_items||[]).map(item=>item.path);
        error=wrapped;
      }
      const report=errorReport.describeError(error);
      journal.event({type:'extraction_failure',stage:'write-or-recover',error_code:error?.code||null,
        message:report.text,rollback:error?.rollback||null,rollback_failures:report.rollback_failures,
        affected_paths:error?.affected_paths||report.affected_paths,entry_cleanup:(meta||error?.entry_result_meta)?.entry_cleanup||null,record_stage:error?.record_stage||null,record_path:error?.record_path||null});
      await journal.finish('failed',{error:{code:error?.code||null,message:report.text,
        rollback:error?.rollback||null,rollback_failures:report.rollback_failures,affected_paths:error?.affected_paths||report.affected_paths}});
      if (!journal.writable) error.log_write_failed=true;
      throw error;
    }
  }

  async function deleteConversation(conversationId, change=null) { const {io}=await requireCurrent(); return applyDelete({io,conversationId,change,now}); }
  
  
  
  
  
  async function archiveConversation(conversationId, change=null) {
    const {io}=await requireCurrent(); const index=await loadIndex(io); const uid=resolveConversationUid(index,conversationId); const entry=uid?index.conversations?.[uid]:null; if(!entry)throw new Error('对话 不在索引中');
    const rules=await readRules(io);
    const active=resolveClassification({conversationId:uid,title:entry.title,indexed:entry,rulesState:rules});
    const current=activeFolder(active.folder||entry.classification?.folder||'未归类'),target=archiveTarget(current);
    const archivedClassification={...active,folder:target};
    const moved=await applyMove({io,conversationId:uid,targetFolder:target,targetClassification:archivedClassification,preserveClassification:true,change,now});
    const latest=await loadIndex(io); markArchived(uid,{index:latest,origin:'local',at:now(),previousFolder:current,previousClassification:active}); await saveIndex(io,latest,now);
    const next=clone(rules); delete next.conversation_overrides[uid]; await writeRules(io,next,{expectedRevision:rules.revision,now});
    return moved;
  }
  async function unarchiveConversation(conversationId, change=null) {
    const {io}=await requireCurrent(); const index=await loadIndex(io); const uid=resolveConversationUid(index,conversationId); const entry=uid?index.conversations?.[uid]:null; if(!entry)throw new Error('对话 不在索引中');
    const rules=await readRules(io);
    const desired=resolveClassification({conversationId:uid,title:entry.title,indexed:{...entry,classification:entry.local_archive_previous_classification||entry.classification,local_state:'active'},rulesState:rules});
    const target=activeFolder(desired.folder||restoreTarget(entry));
    const restoredClassification={...desired,folder:target};
    const moved=await applyMove({io,conversationId:uid,targetFolder:target,targetClassification:restoredClassification,preserveClassification:true,change,now});
    const latest=await loadIndex(io); markRestored(uid,{index:latest,at:now()}); await saveIndex(io,latest,now);
    const next=clone(rules); delete next.conversation_overrides[uid]; await writeRules(io,next,{expectedRevision:rules.revision,now}); return moved;
  }


