    if(conversationClosure.bytes_complete)summary.bytes_complete_conversations+=1;
    if(conversationClosure.processing_closed)summary.processing_closed_conversations+=1;
    const verifiedEmpty=Boolean(discovery.verified)&&conversationClosure.active_relation_asset_count===0&&Number(state.attachment_count||0)===0;
    if(verifiedEmpty)summary.verified_empty_conversations+=1;
    else if(Boolean(discovery.verified)&&conversationClosure.bytes_complete)summary.complete_conversations+=1;
