"src/runtime/auto-check.js": function(module, exports, require) {
'use strict';
(function (module, exports, require) {

'use strict';















const DEFAULT_INTERVAL_MS = 10 * 60 * 1000;     
const MIN_INTERVAL_MS = 30 * 1000;             







function autoCheckDecision({ lastCheckAt = null, nowMs = Date.now(), writeTaskRunning = false, libraryAvailable = true, checkInFlight = false, intervalMs = DEFAULT_INTERVAL_MS } = {}) {
  const interval = Math.max(MIN_INTERVAL_MS, Number(intervalMs) || DEFAULT_INTERVAL_MS);
  if (!libraryAvailable) return { run: false, reason: 'library-unavailable', interval_ms: interval, age_ms: null };
  if (checkInFlight) return { run: false, reason: 'check-in-flight', interval_ms: interval, age_ms: null };
  if (writeTaskRunning) return { run: false, reason: 'write-task-running', interval_ms: interval, age_ms: null };
  const at = lastCheckAt ? Date.parse(String(lastCheckAt)) : NaN;
  if (!Number.isFinite(at)) return { run: true, reason: 'never-checked', interval_ms: interval, age_ms: null };
  const age = Math.max(0, Number(nowMs) - at);
  if (age < interval) return { run: false, reason: 'checked-recently', interval_ms: interval, age_ms: age };
  return { run: true, reason: 'ok', interval_ms: interval, age_ms: age };
}


function localCheckFreshness({ state = null, nowMs = Date.now(), intervalMs = DEFAULT_INTERVAL_MS } = {}) {
  const interval = Math.max(MIN_INTERVAL_MS, Number(intervalMs) || DEFAULT_INTERVAL_MS);
  const at = state?.at ? String(state.at) : null;
  const parsed = at ? Date.parse(at) : NaN;
  if (!Number.isFinite(parsed)) return { at: null, age_ms: null, fresh: false, label: '还没检查过本地变化' };
  const age = Math.max(0, Number(nowMs) - parsed);
  const minutes = Math.floor(age / 60000);
  const label = minutes < 1 ? '刚刚检查过本地变化' : `${minutes} 分钟前检查过本地变化`;
  return { at, age_ms: age, fresh: age < interval, label, stale: age >= interval };
}


function localCheckLine({ state = null, decision = null, nowMs = Date.now() } = {}) {
  if (decision && !decision.run && decision.reason !== 'checked-recently' && decision.reason !== 'ok') {
    const why = {
      'write-task-running': '现在有别的任务在写资料库，等它处理结束再看（不跟写任务抢）',
      'library-unavailable': '资料库还没接手（或权限没给），看不了本地变化',
      'check-in-flight': '上一次检查还在跑',
    }[decision.reason] || decision.reason;
    return `本地变化自动检查：这次没查 —— ${why}`;
  }
  const freshness = localCheckFreshness({ state, nowMs });
  
  
  
  
  const bodyNote = String(state?.body_scan_note || '').trim();
  const detail = state?.pending ? ` · 上次有 ${state.pending} 项待确认` : '';
  return `本地变化自动检查：${freshness.label}${detail}${bodyNote ? ` · ${bodyNote}` : ''}。`
    + '它看的是：对话位置、目录变化、附件本体、以及你改过的正文；**只在打开面板那一刻发生**（页面关掉就没有东西在监听磁盘）。'
    + '想彻底重扫就点上面那个「检查变化」。';
}

module.exports = { DEFAULT_INTERVAL_MS, AUTO_CHECK_INTERVAL_MS: DEFAULT_INTERVAL_MS, MIN_INTERVAL_MS, autoCheckDecision, localCheckFreshness, localCheckLine };
})(module, module.exports, require);

},
