  let pendingUpgradeReport=null;
  /* [REV-2026-10-08] **老库接管的独立入口**（用户给的二选一里的 ①：给接管一个独立入口，
     不许变回第 4 种待处理）。依据：登记表 `management/pending-catalog.js:73-74` 已把
     `library-upgrade` 判成 `where:'auto'`，于是 `pendingDecisionModel` 对它是 `renderable:false` ——
     再借待处理那一层渲染，出来的就是**一张没有按钮的卡**（`renderPending` 会把它当"已自动处理"剔掉，
     用户什么也点不了）。现在接管 = 管理站首页上**自己的一块动作区**
     （`[data-manage-takeover-group]`，markup 在 `ui/stations/manage-view.js` 的 `hubMarkup`），
     只在 snapshot 说"需要升级"（`library_kind==='upgrade_required'`）时才亮。
     它**不进 `pending`、不过登记闸、不占待处理那一层** —— 所以它不是第 4 种待处理。 */
  function paintTakeoverEntry(){
    const group=$('[data-manage-takeover-group]');
    if(!group)return;
    group.classList.toggle('hidden',String(snapshot?.library_kind||'')!=='upgrade_required');
  }
  $$('[data-manage-takeover]').forEach(button=>button.addEventListener('click',()=>{if(busy)return;void openLibraryUpgrade(null,{mode:button.dataset.manageTakeover})}));
  async function openLibraryUpgrade(lib,{mode=null}={}){
    setBusy(true,c('shell.dock.checking.library'),c('shell.dock.checking.library.detail'));
    try{
      const report=await appController.inspectLibraryUpgrade();
      pendingUpgradeReport=report;
      if(!report?.needed){
        emitStatusMessage(report?.message||c('shell.dock.library.no.upgrade'),{tone:'info',ttlMs:6000});
        await refreshSnapshot();return report
      }
      /* 从「检查变化 / 选库」那条路过来的（没点名方式）：**不擅自升级**，只把首页那块入口亮出来，
         让用户自己挑一种 —— 在用户挑之前不动任何文件。 */
      if(!mode){
        paintTakeoverEntry();
        emitStatusMessage(report.message||c('shell.manage.take.over.old.library'),{tone:'warning',ttlMs:12000});
        return report;
      }
      /* 首页那块动作区点了哪一种就走哪一种：`in-place` = 原地升级后接管；
         `new-directory` = 另存为新目录（会开系统文件夹框）再接管。 */
      return await runLibraryUpgradeFromDecision(mode);
    }catch(error){showError(error);return null}
    finally{setBusy(false);await refreshSnapshot()}
  }
  async function runLibraryTakeoverFromDecision(){
    setBusy(true,c('shell.dock.taking.over'),c('shell.dock.taking.over.detail'));
    try{
      const result=await appController.runLibraryTakeover({
        onProgress:(event)=>setBusy(true,c('shell.dock.taking.over'),event?.message||c('shell.dock.taking.over.progress')),
      });
      pendingUpgradeReport=null;
      emitStatusMessage(result.message,{tone:result.status==='adopted'?'ok':'warning',ttlMs:12000});
      return result;
    }catch(error){showError(error);return null}
    finally{pendingUpgradeReport=null;pending=[];closePending();setBusy(false);await refreshSnapshot()}
  }
  
  
  
  
  
  
  
  async function runLibraryUpgradeFromDecision(mode){
    setBusy(true,c('shell.dock.upgrading'),c('shell.dock.upgrading.detail'));
    try{
      const result=await appController.runLibraryUpgrade({
        mode,
        onProgress:(event)=>{const pos=event?.position&&event?.total?` ${event.position}/${event.total}`:'';setBusy(true,t('shell.dock.upgrading.pos',{pos}),event?.target_path?t('shell.dock.upgrading.target',{path:event.target_path}):c('shell.dock.upgrading.plain'))},
      });
      pendingUpgradeReport=null;
      emitStatusMessage(result.message,{tone:result.status==='complete'?'ok':'warning',ttlMs:12000});
      
      
      if(result.status==='complete'){return await runLibraryTakeoverFromDecision()}
      return result;
    }catch(error){showError(error);return null}
    finally{pendingUpgradeReport=null;pending=[];closePending();setBusy(false);await refreshSnapshot()}
  }
  







  async function warnPendingUpgrade(){
    let record=null;
    try{record=await appController.libraryUpgradePending?.()}catch{return}
    if(!record)return;
    const target=String(record.target_name||'').trim();
    const copied=Number(record.copied||0),failed=Number(record.failed||0);
    const when=String(record.at||'').slice(0,16).replace('T',' ');
    const parts=[
      target?t('shell.dock.move.target', { target }):c('shell.dock.move.target.unknown'),
      copied?t('shell.dock.move.copied', { n: copied }):c('shell.dock.move.none'),
      failed?t('shell.dock.move.failed', { n: failed }):'',
      when?t('shell.dock.move.when', { when }):'',
    ].filter(Boolean);
    emitStatusMessage(c('shell.dock.move.pending'),{
      detail:`${parts.join(' · ')}。它**还在原地等着**：再走一次同一个入口、把那个目标文件夹再选一次，就会**从已经搬过去的地方接着做**（搬过的不会重来）。`,
      tone:'warning',ttlMs:14000,
    });
  }
