  async function renderUnavailableBox(scope){
    try{
      const copy=$('[data-attachment-unavailable-copy]',scope),list=$('[data-attachment-unavailable-list]',scope);
      if(!copy||!list)return;
      const data=typeof appController.unavailableAttachments==='function'?await appController.unavailableAttachments():null;
      const lastLine=$('[data-attachment-unavailable-last]',scope);
      if(lastLine)lastLine.textContent=unavailableLastLine(data);
      const rows=((data&&data.rows)||[]).filter(row=>!row.abandoned);
      
      const restoreBtn=$('[data-attachment-unavailable-restore]',scope);
      if(restoreBtn){
        const abandonedCount=Number((data&&data.abandoned)||0)||0;
        restoreBtn.style.display=abandonedCount?'':'none';
        if(abandonedCount)restoreBtn.textContent=t('shell.dock.undo.abandon.title', { n: abandonedCount });
      }
      

      if(!rows.length){copy.textContent=attachmentView.unavailableCopyText({count:0,abandoned:Number((data&&data.abandoned)||0)||0});list.innerHTML='';return}
      copy.textContent=attachmentView.unavailableCopyText({count:rows.length,abandoned:Number((data&&data.abandoned)||0)||0});
      list.innerHTML=attachmentView.unavailableRowsMarkup(rows);
    }catch(error){
      
      const copy=$('[data-attachment-unavailable-copy]',scope);
      if(copy)copy.textContent=t('shell.dock.list.read.failed', { message: friendlyError(error) });
    }
  }
  
  async function rerenderUnavailableBoxFrom(el){ const scope=el?.closest?.('[data-attachment-unavailable-box]')||null; if(scope)await renderUnavailableBox(scope); }
  




