  const source=conversationSourceOf(entry);
  const sourceLabel=source==='self'?c('shell.manage.source.self'):source==='project'?c('shell.manage.source.project'):c('shell.manage.source.all.conversations');
  const folder=folderLabel(entry);
  const time=timeLabel(entry.update_time||entry.create_time);
  const meta=[sourceLabel,folder].filter(Boolean).join(' · ');
  return {id,state,source,stateLabel,title:entry.title||c('shell.manage.untitled.conversation'),meta,time};
