  async function switchLibraryAxis(scope,target){
    if(busy)return;
    const holder=$('[data-library-axis]',scope),seg=$('[data-library-axis-seg]',scope);
    const current=String(holder?.value||'classification');
    const next=String(target||current);
    if(next===current){setSeg(seg,current);return;}
    setSeg(seg,next);
    const label=next==='project'?c('shell.manage.axis.project.out.long'):c('shell.manage.axis.self.out.long');
    const yes=windowImpl.confirm?.(`把库的主视图换成「${label}」？\n\n这会**搬全库**：每条对话的文件都要挪到新位置（几十条的话就是几百上千个文件）。\n规矩：先复制 → 读回核对 → 记账 → 才删旧；**目标位置已经有东西的一律不动**、如实报；\n中途可以关页面，下次进来接着搬。`);
    if(!yes){setSeg(seg,current);return;}
    setBusy(true,c('shell.manage.axis.switching'),c('shell.manage.axis.switching.detail'));
    try{
      const result=await appController.setLibraryAxis({axis:next});
      emitStatusMessage(result?.message||c('shell.manage.axis.switched'),{detail:c('shell.manage.axis.switched.detail'),ttlMs:14000});
      await refreshSnapshot();
      await refreshLibraryAxisBox(scope);
    }catch(error){
      setSeg(seg,current);
      emitStatusMessage(errorText(error,c('shell.manage.axis.change.label')),{tone:'error'});
      await refreshLibraryAxisBox(scope);
    }finally{setBusy(false)}
  }
  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
  







  let layerDraftOrder=null;                    
  let layerSavedOrder=null;                    
  function layerOrderFromSnapshot(){
    const rows=layerRows(snapshot?.layer_order||undefined);
    return rows.rows.filter(row=>row.enabled).map(row=>row.layer);
  }
  function renderLayerOrder(scope){
    const list=$('[data-save-layer-checks]',scope),note=$('[data-save-layer-note]',scope);
    if(!list)return;
    const grid=$('.chipgrid',list);
    const known=Array.isArray(snapshot?.layer_order);
    if(!known){
      
      $$('[data-layer-row]',list).forEach(row=>{row.disabled=true});
      if(note)note.textContent=c('shell.set.layers.unavailable');
      const saveButton=$('[data-save-layer-save]',scope);if(saveButton)saveButton.disabled=true;
      const toggle=$('[data-save-layer-toggle]',scope);if(toggle)toggle.disabled=true;      
      return;
    }
    if(!layerDraftOrder)layerDraftOrder=layerOrderFromSnapshot();
    layerSavedOrder=layerOrderFromSnapshot();
    const baseRows=layerRows(['json','markdown','pdf','word']).rows;
    const draftRank=new Map((layerDraftOrder||[]).map((key,index)=>[String(key),index+1]));
    const rows={rows:baseRows.map((info)=>({...info,enabled:draftRank.has(info.layer),number:draftRank.get(info.layer)||null}))};
    const dirty=JSON.stringify(layerDraftOrder)!==JSON.stringify(layerSavedOrder);
    
    const dirs=layerDirectories(layerDraftOrder);
    const byLayer=new Map(rows.rows.map(row=>[row.layer,row]));
    const ordered=rows.rows;
    for(const info of ordered){
      const row=$(`[data-save-layer="${info.layer}"]`,list);if(!row)continue;
      row.disabled=false;
      

      if(row.dataset.layerName===undefined)row.dataset.layerName=String(byLayer.get(info.layer)?.label||info.layer||'');
      const name=row.dataset.layerName;
      row.textContent=info.number?`${String(info.number).padStart(2,'0')} ${name}`:name;
      row.classList.toggle('enabled',info.enabled);
      row.dataset.on=String(Boolean(info.enabled));
      

      row.style.removeProperty('order');
      



      if(grid&&row.parentNode!==grid)grid.appendChild(row);
    }
    

    const saveButton=$('[data-save-layer-save]',scope);
    if(saveButton)saveButton.disabled=!dirty;
    if(note){
      

      const lines=layerDraftOrder.map(key=>`${String(byLayer.get(key)?.number||0).padStart(2,'0')}_${(byLayer.get(key)?.label)||key}`).join(' · ');
      const nowDirs=layerSavedOrder.map(key=>dirsOf(layerSavedOrder).find(name=>name.endsWith(`_${byLayer.get(key)?.label||''}`))||key).join(' · ');
      if(!layerDraftOrder.length)note.textContent=c('shell.set.layers.need.one.hint');
      else if(!dirty)note.textContent=t('shell.set.layers.now', { lines });
      else note.textContent=t('shell.set.layers.preview', { lines, now: nowDirs||'—' });
    }
    




    const toggleButton=$('[data-save-layer-toggle]',scope);
    if(toggleButton){
      toggleButton.disabled=false;
      const hasSelection=(layerDraftOrder||[]).length>0;
      toggleButton.textContent=hasSelection?c('shell.common.clear'):c('shell.common.select.all');
      if(!toggleButton.dataset.wired){toggleButton.dataset.wired='1';toggleButton.addEventListener('click',()=>{
        const hasAny=(layerDraftOrder||[]).length>0;
        layerDraftOrder=hasAny?[]:['json','markdown','pdf','word'];
        renderLayerOrder(scope);
      })}
    }
    for(const row of $$('[data-save-layer]',list)){
      if(row.dataset.wired)continue;row.dataset.wired='1';
      row.addEventListener('click',()=>{
        const key=String(row.dataset.saveLayer||'');
        if(!key)return;
        const order=[...(layerDraftOrder||[])];
        const at=order.indexOf(key);
        if(at>=0)order.splice(at,1);else order.push(key);   
        layerDraftOrder=order;renderLayerOrder(scope);
      });
    }
    if(saveButton&&!saveButton.dataset.wired){
      saveButton.dataset.wired='1';
      saveButton.addEventListener('click',()=>{void applyLayerOrder(scope)});
    }
  }
  function dirsOf(order){return Object.values(layerDirectories(order||[]))}
  async function applyLayerOrder(scope){
    if(busy)return;
    const note=$('[data-save-layer-note]',scope);
    const order=[...(layerDraftOrder||[])];
    try{
      

      setBusy(true,c('shell.set.layers.computing'),c('shell.set.layers.computing.detail'));
      const preview=await appController.saveLayerLayout({order,confirm:false});
      const text=preview?.text||'';
      if(!preview?.changed){
        setBusy(false);
        if(note)note.textContent=t('shell.set.layers.no.change', { text });
        emitStatusMessage(c('shell.set.layers.no.change.plain'),{detail:text,ttlMs:7000});
        return;
      }
      setBusy(false);
      if(note)note.textContent=t('shell.set.layers.changes', { text });
      
      const yes=windowImpl.confirm?.(`按你排的号改盘上的目录：\n\n${text}\n\n关掉的那几层只是名字后面加「（冻结）」，**东西一个都不删**。资料库记录会一起更新路径。\n\n就按这个改吗？`);
      if(!yes){emitStatusMessage(c('shell.set.layers.unchanged'));return}
      acknowledgeCommand(c('shell.set.layers.save'));
      setBusy(true,c('shell.set.layers.renaming'),c('shell.set.layers.renaming.detail'));
      const result=await appController.saveLayerLayout({order,confirm:true,onProgress:async(event)=>{
        const done=Number(event?.moved||0)+Number(event?.skipped||0);
        setBusy(true,t('shell.set.layers.renaming.step.title',{what:event?.what||c('shell.set.layers.renaming.default'),from:event?.from||'',to:event?.to||'',moved:done?t('shell.set.layers.renaming.moved',{n:done}):''}),c('shell.set.layers.renaming.step'));
      }});
      await refreshSnapshot();
      layerDraftOrder=null;                        
      renderLayerOrder(scope);
      const failed=(result?.results||[]).filter(item=>!item.ok);
      
      
      const catchupLines=(result?.catchup||[]).map((item)=>item.message).filter(Boolean);
      const catchupText=catchupLines.length?` ${catchupLines.join('；')}。`:'';
      if(failed.length)emitStatusMessage(t('shell.set.layers.stopped',{from:failed[0].from,to:failed[0].to}),{tone:'warn',detail:t('shell.set.layers.stopped.detail',{catchup:catchupText}),ttlMs:12000});
      else emitStatusMessage(c('shell.set.layers.done'),{detail:t('shell.set.layers.done.detail',{text:result?.text||'',catchup:catchupText}),ttlMs:catchupLines.length?12000:8000});
    }catch(error){
      setBusy(false);
      
      
      const message=errorText(error,c('shell.set.layers.label'));
      if(note)note.textContent=t('shell.set.layers.failed',{message:friendlyError(error)});
      emitStatusMessage(message,{tone:'error',ttlMs:12000});
    }finally{setBusy(false);clearCommandAcknowledgement();void drainPickerQueue()}
  }
  

