  let supplementState = { step: 0, reached: 0, queue: [], selection: null, inspection: null, result: null };
  

  function pickLocalFileForClaim() {
    return new Promise((resolve) => {
      const input = documentImpl.createElement('input');
      input.type = 'file';
      input.style.display = 'none';
      let settled = false;
      const finish = (value) => { if (settled) return; settled = true; input.remove?.(); resolve(value); };
      input.addEventListener('change', () => {
        const file = input.files?.[0] || null;
        if (!file) { finish(null); return; }
        Promise.resolve(typeof file.arrayBuffer === 'function' ? file.arrayBuffer() : null)
          .then((buffer) => finish(buffer ? { fileName: String(file.name || ''), sizeBytes: Number(file.size || 0), bytes: new Uint8Array(buffer) } : null))
          .catch(() => finish(null));
      });
      
      input.addEventListener('cancel', () => finish(null));
      documentImpl.body?.appendChild?.(input);
      input.click?.();
    });
  }
  
  function supplementCountText(){return Array.isArray(supplementState.queue)?supplementState.queue.filter((row)=>!row.abandoned).length:0}
  async function loadSupplementQueue() {
    const data = typeof appController.manualSupplementQueue === 'function'
      ? await appController.manualSupplementQueue({ targetKind: 'conversation_attachment' })
      : null;
    return Array.isArray(data?.rows) ? data.rows : [];
  }
  function supplementRenderModel(){return {step:supplementState.step,reached:supplementState.reached,queue:supplementState.queue,selection:supplementState.selection,inspection:supplementState.inspection,result:supplementState.result}}
  function attachmentBody(){return activeManage&&activeManage.dataset.manage==='attachments'?$('[data-manage-body]',activeManage):null}
  function repaintSupplement(){const body=attachmentBody();if(!body)return;renderAttachmentCenterBody(body);setAttachmentFace(body,'supplement')}
  
  async function openSupplementWorkspace(){
    supplementState = { step: 0, reached: 0, queue: await loadSupplementQueue(), selection: null, inspection: null, result: null };
    repaintSupplement();
    
    const body = attachmentBody();
    if (body) void renderUnavailableBox(body);
  }
  
  async function supplementChooseAttachment(attachmentId){
    const row = (supplementState.queue || []).find((item) => String(item.attachment_id) === String(attachmentId)) || null;
    if (!row) { emitStatusMessage(c('shell.attachment.supplement.not.in.queue')); return }
    supplementState.selection = null; supplementState.inspection = null; supplementState.result = null;
    supplementState.step = 1; supplementState.reached = Math.max(supplementState.reached, 1);
    const picked = await pickLocalFileForClaim();
    if (!picked) { repaintSupplement(); emitStatusMessage(c('shell.dock.no.file.picked')); return }
    await supplementInspectPicked(row, picked);
  }
  
  async function supplementInspectPicked(row, picked){
    try {
      setBusy(true, c('shell.attachment.checking.this'));
      const inspection = await appController.inspectManualClaim({ attachmentId: String(row.attachment_id), fileName: picked.fileName, sizeBytes: picked.sizeBytes, bytes: picked.bytes });
      supplementState.selection = { attachmentId: String(row.attachment_id), name: picked.fileName, sizeBytes: picked.sizeBytes, bytes: picked.bytes };
      supplementState.inspection = inspection;
      supplementState.step = 2; supplementState.reached = Math.max(supplementState.reached, 3);
      repaintSupplement();
    } catch (error) { showError(error) } finally { setBusy(false) }
  }
  
  async function supplementCommit(userConfirmed){
    const sel = supplementState.selection;
    if (!sel || !sel.bytes) { emitStatusMessage(c('shell.attachment.no.file.selected')); return }
    try {
      setBusy(true, userConfirmed ? c('shell.attachment.receiving.confirmed') : c('shell.attachment.receiving'));
      const result = await appController.registerManualAttachment({ attachmentId: sel.attachmentId, bytes: sel.bytes, fileName: sel.name, sizeBytes: sel.sizeBytes, userConfirmed: Boolean(userConfirmed) });
      supplementState.result = { message: String(result?.message || c('shell.dock.received')) };
      supplementState.step = 4; supplementState.reached = 4;
      supplementState.queue = await loadSupplementQueue();
      await refreshSnapshot();
      

      if (!supplementState.queue.filter((row) => !row.abandoned).length) {
        emitStatusMessage(String(result?.message || c('shell.dock.received')), { detail: c('shell.attachment.nothing.to.supplement'), ttlMs: 9000 });
        const body = attachmentBody();
        if (body) { renderAttachmentCenterBody(body); setAttachmentFace(body, 'integrity') }
        return;
      }
      repaintSupplement();
    } catch (error) {
      
      if (error?.inspection) supplementState.inspection = error.inspection;
      showError(error);
      repaintSupplement();
    } finally { setBusy(false) }
  }
