    const field=$('[data-rule-field]',editor).value.trim().toUpperCase()||'TAG',conn=ruleConnectorValue(editor),mode=$('[data-sub-mode]',editor).value,root=$('[data-rule-root]',editor).value.trim()||c('shell.common.uncategorized'),sub=mode==='none'?'':$('[data-rule-sub]',editor).value.trim(),sep=ruleSeparatorValue(editor);$('[data-sub-row]',editor).classList.toggle('hidden',mode==='none');$('[data-rule-connector-custom]',editor)?.classList.toggle('hidden',$('[data-rule-connector]',editor).value!=='__custom__');$('[data-sub-custom]',editor)?.classList.toggle('hidden',mode!=='custom');{const _fmt=`${field}${conn===' '?c('shell.manage.delimiter.space.bracket'):conn||c('shell.manage.delimiter.none.bracket')}${c('shell.manage.rule.preview.name')}`;const f=$('[data-preview-format]',editor);if(f)f.textContent=_fmt;const s=$('[data-sum-pattern]',editor);if(s)s.textContent=_fmt;}const _path=[root,sub].filter(Boolean).join(' / ')||c('shell.common.uncategorized');{const p=$('[data-preview-path]',editor);if(p)p.textContent=_path;const s=$('[data-sum-path]',editor);if(s)s.textContent=_path;}{const _eg=t('shell.manage.rule.preview.example',{field,conn});const e=$('[data-preview-example]',editor);if(e)e.textContent=_eg;const s=$('[data-sum-example]',editor);if(s)s.textContent=_eg;}if(mode!=='none'&&sub&&sep&&!sub.includes(sep)&&sub.includes('/'))$('[data-preview-path]',editor).textContent=[root,...sub.split('/')].filter(Boolean).join(' / ');{const titleEl=$('[data-rule-editor-title]',editor);if(titleEl)titleEl.textContent=field||c('shell.manage.new.short')}
