    if(item.type==='title-candidate')return{title:t('shell.manage.pending.remote.title',{label:titleCandidateLabel(item)}),copy:t('shell.manage.pending.remote.title.copy',{n:Number(item.count||0),example:(item.examples||[])[0]||''})};
