function pickerFilterConditions(filters = {}, { rowCount = null, shownCount = null } = {}) {
  const value = filters || {};
  const active = [];
  const query = String(value.query || '').trim();
  if (query) active.push({ key: 'query', label: t('shell.extract.filter.query', { query }) });
  if (value.state === 'archived') active.push({ key: 'state', label: c('shell.extract.only.archived') });
  else if (value.state === 'all') active.push({ key: 'state', label: c('shell.filter.current.archive') });
  if (value.time && value.time !== 'all') active.push({ key: 'time', label: value.time === '7d' ? c('shell.filter.last.7d') : value.time === '30d' ? c('shell.filter.last.30d') : `${c('shell.filter.custom.time')} ${value.startDate||'…'}～${value.endDate||'…'}` });
  if (value.classification) active.push({ key: 'classification', label: t('shell.extract.filter.classification', { name: value.classification }) });
  if (value.folder) active.push({ key: 'folder', label: t('shell.extract.filter.folder', { name: value.folder, sub: value.includeSubfolders === false ? c('shell.extract.filter.no.subfolders') : '' }) });
  const summary = active.map((item) => item.label).join(' · ');
  let empty = '';
  if (Number(shownCount) === 0) {
    if (Number(rowCount) > 0 && active.length) {
      empty = `这个库里现在有 ${Number(rowCount)} 条对话，但**没有一条同时满足**：${summary}。放宽条件，或者点「清空筛选」就能看到全部。`;
    } else if (Number(rowCount) > 0) {
      empty = t('shell.extract.empty.loading', { n: Number(rowCount) });
    } else {
      empty = c('shell.extract.empty.none');
    }
  }
  return { active, summary, empty, has_conditions: active.length > 0 };
}




