    authorized_existing_paths:{...authorizedExistingPaths},
    cleanup_paths:[],
    recovery_evidence:{version:1,base_files:{},base_index_known:Boolean(index),base_index:copy(index?.conversations?.[effectiveUid]||null),final_write_started:false,index_write_started:false},
