    const seen=observations[kind]=await observeFile(io,record.final_paths[kind],cryptoImpl);
    const isTarget=seen.exists && seen.sha256===record.hashes[kind];
    const isBase=evidence?.base_files?.[kind] ? sameObservation(seen,evidence.base_files[kind]) : !seen.exists;
