  const preview=await pendingDecisionPreview({io,pendingPath,index,cryptoImpl});
  if (preview.token!==token) throw Object.assign(new Error('pending or current content changed; review again'),{code:'pending_decision_stale'});
  const evidencePath=await archivePendingEvidence({io,pendingPath,record:preview.record,reason:decision,observations:preview.safety,cryptoImpl});
