async function commitConversation(args) {
  const prepared = await prepareConversationCommit(args);
  return recoverPendingCommit({
    io: args.io,
    pendingPath: prepared.pendingPath,
    index: args.index,
    persistIndex: args.persistIndex,
    cryptoImpl: args.cryptoImpl,
  });
}

async function commitUnavailableConversation(args) {
  return commitConversation({ ...args, artifactKinds: LOCAL_UNAVAILABLE_ARTIFACTS });
}

