"src/ui/html.js": function(module, exports, require) {
'use strict';










(function (module, exports, require) {

  

  function esc(value) {
    return String(value ?? '').replace(/[&<>"']/g, (ch) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch]));
  }

  module.exports = { esc };
})(module, module.exports, require);

},
