"src/ui/idle-maintenance.js": function(module, exports, require) {
'use strict';
const { createCooperativeScheduler } = require('../runtime/cooperative-scheduler');
function createIdleMaintenance({ windowImpl = globalThis, isOpen, isBusy, jobs = [], onError = () => {} } = {}) {
  let generation = 0, timer = null, idle = null;
  const scheduler = createCooperativeScheduler();
  function cancel() {
    generation += 1;
    if (timer !== null) windowImpl.clearTimeout(timer);
    if (idle !== null) windowImpl.cancelIdleCallback?.(idle);
    timer = idle = null;
  }
  function schedule() {
    cancel(); const token = generation;
    const valid = () => token === generation && isOpen();
    async function run() {
      if (!valid()) return;
      for (const job of jobs) {
        if (!valid()) return;
        if (isBusy()) {
          timer = windowImpl.setTimeout(() => { if (valid()) schedule(); }, 700);
          return;
        }
        try { await job(); } catch (error) { onError(error); }
        await scheduler.yieldIfNeeded({ force: true });
      }
    }
    if (typeof windowImpl.requestIdleCallback === 'function') idle = windowImpl.requestIdleCallback(() => { idle = null; void run(); }, { timeout: 1800 });
    else timer = windowImpl.setTimeout(() => { timer = null; void run(); }, 700);
  }
  return { schedule, cancel };
}
module.exports = { createIdleMaintenance };

},
