    setPagerDot: { where: '页码点：亮灭', parts: [['background', '.2s', 'ease'], ['transform', '.2s', 'ease']] },
    setDialTrack: { where: '右侧无限轮盘：轨道跟着走', parts: [['transform', '.3s', 'ease']] },
    setDialItem: { where: '轮盘上的书签（`.set-dseg`）', parts: [['color', '.22s', 'ease'], ['transform', '.22s', 'ease'], ['opacity', '.22s', 'ease']] },
