      + '<div class="attachment-supplement-list">' + listBody + '</div>'
      

      + (typeof unavailableBoxMarkup === 'function' ? unavailableBoxMarkup() : '')
      + '</section>';

    
    const step1 = '<section class="attachment-center-section"><h4>' + c('attachment.supplement.step1.title') + '</h4>'
