          + '<div class="attachment-result-grid">'
          + '<div class="attachment-result-row"><strong>' + esc(triMark(insp.name_matches, c('attachment.common.match'), c('attachment.common.mismatch'), c('attachment.common.unverifiable'))) + '</strong><span>' + c('attachment.inspect.name') + '</span><small>' + esc(sel ? sel.name : '') + '</small></div>'
          + '<div class="attachment-result-row"><strong>' + esc(triMark(insp.type_matches, c('attachment.common.match'), c('attachment.common.mismatch'), c('attachment.common.unverifiable'))) + '</strong><span>' + c('attachment.inspect.type') + '</span><small>' + c('attachment.inspect.type.note') + '</small></div>'
          + '<div class="attachment-result-row"><strong>' + esc(triMark(insp.size_matches, c('attachment.common.match'), c('attachment.common.mismatch'), c('attachment.common.unverifiable'))) + '</strong><span>' + c('attachment.inspect.size') + '</span><small>' + esc(sel && sel.sizeBytes != null ? sel.sizeBytes + ' ' + c('attachment.unit.bytes') : '') + '</small></div>'
          + '<div class="attachment-result-row"><strong>' + esc(insp.expected_sha256 && insp.selected_sha256 && insp.expected_sha256 === insp.selected_sha256 ? c('attachment.common.match') : c('attachment.common.mismatch')) + '</strong><span>' + c('attachment.inspect.hash') + '</span>'
          + '<small>' + c('attachment.inspect.expected') + ' ' + esc(String(insp.expected_sha256 || '—').slice(0, 16)) + ' / ' + c('attachment.inspect.selected') + ' ' + esc(String(insp.selected_sha256 || '—').slice(0, 16)) + '</small></div>'
          + '</div>'
