    return '<div class="attachment-face-nav" data-attachment-face-nav>'
      + [[ 'integrity', c('attachment.nav.integrity'), c('attachment.nav.integrity.title') ], [ 'organize', c('attachment.nav.organize'), c('attachment.nav.organize.title') ], [ 'shelf', c('attachment.nav.shelf'), c('attachment.nav.shelf.title') ]]
        .map(([key, label, title], index) => '<button class="bottomitem' + (index === 0 ? ' active' : '') + '" data-attachment-face-go="' + key + '" title="' + esc(title) + '" type="button">'
          + icon('face-' + key) + '<span>' + esc(label) + '</span></button>').join('')
      + '</div>';
