  function filterOptionsMarkup(values, allLabel) {
    return `<option value="">${esc(allLabel)}</option>`
      + (values || []).map((item) => {
        const value = typeof item === 'string' ? item : item?.value;
        const label = typeof item === 'string' ? item : item?.label;
        return `<option value="${esc(value || '')}">${esc(label || value || '')}</option>`;
      }).join('');
  }

  


  function rowMarkup(row = {}) {
    return `<div class="pick-row ${row.selected ? 'selected' : ''}" data-pick-row data-id="${esc(row.ref)}">`
      + '<div class="rail"></div><div><div class="pick-title-line"><div class="pick-title">' + esc(row.title || c('export.row.untitled')) + '</div>'
      + '<span class="human-badge hidden" data-human-badge>' + c('export.row.human.badge') + '</span></div>'
      + `<div class="pick-meta">${esc(row.meta || '')}</div></div>`
      + `<div class="pick-time">${esc(row.time || '')}</div></div>`;
  }

  function rowsMarkup(rows = [], emptyText = '') {
    return rows.map(rowMarkup).join('')
      || `<div class="hint" style="padding:14px">${esc(emptyText || c('export.rows.empty'))}</div>`;
  }

  









  

  function countLineText({ shown = 0, total = 0, lastSyncText = c('export.readout.never.synced') } = {}) {
    

    


    const more = total > shown ? c('export.readout.more') : '';
    return t('export.readout.count', { shown, total, more, sync: lastSyncText });
  }

  

  function humanScopeChipsMarkup(affected = []) {
    return affected.map((item) => {
      const title = esc(item.title || item.ref);
      
      return `<span class="human-scope-chip" title="${title}">${t('extract.human.chip', { count: item.humanCount || 1, title })}</span>`;
    }).join('');
  }

  function humanPerListMarkup({ affected = [], choices = new Map() } = {}) {
    return affected.map((item, i) => {
      const key = String(item.ref);
      const choice = choices.get(key) || '';
      return '<div class="human-per-row">'
        + `<div class="human-per-title" title="${esc(item.title || item.ref)}">${esc(item.title || item.ref)}</div>`
        + '<div class="human-per-options">'
        + `<label><input type="radio" name="acf-per-${i}" value="composed" data-scope-key="${esc(key)}" ${choice === 'composed' ? 'checked' : ''}>${c('extract.human.keep.composed')}</label>`
        + `<label><input type="radio" name="acf-per-${i}" value="platform" data-scope-key="${esc(key)}" ${choice === 'platform' ? 'checked' : ''}>${c('extract.human.keep.platform')}</label>`
        + '</div></div>';
    }).join('');
  }


  







  








