    const inEl = pageEl(keys[next], scope);
    const wrap = $('[data-set-pages-wrap]', scope);
    if (noMotion() || !outEl || !inEl || !wrap) { pageIndex = next; paint(scope); return; }
    const ghost=outEl.cloneNode(true);
    ghost.removeAttribute('data-set-page');ghost.setAttribute('data-set-page-ghost','1');ghost.setAttribute('aria-hidden','true');
    ghost.classList.remove('hidden','set-flip-out-fwd','set-flip-in-fwd','set-flip-out-bwd','set-flip-in-bwd');
    ghost.classList.add('set-page-ghost',dir>0?'set-page-ghost-fwd':'set-page-ghost-bwd');
