  const hasLegacyMeta = normalized.some((p) => p === '.chatgpt-export' || p.startsWith('.chatgpt-export/'));
  const hasPublicIndex = normalized.includes('conversation-index.json');
  const hasInternalIndex = normalized.includes('.chatgpt-export/index.json');
  const hasLegacyJsonFiles = normalized.some((p) => p.startsWith('JSON/') && p.toLowerCase().endsWith('.json'));
